/* Notes for the system design guide's diagrams, keyed sd:<owner>[:<title>]. See figures/notes.js. */
window.FIG_NOTES = Object.assign(window.FIG_NOTES || {}, {
  "sd:agent-durability:stateless-loop-durable-state": {"nodes": {"queue": {"d": "The task queue holds work items with leases: a worker claims a task by taking out a time-limited lease on it, and the lease can expire and be reclaimed if the worker disappears.", "links": [{"label": "Technique: leases for ownership", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/worker-leases"}]}, "stream": {"d": "The event stream records what the agent does as a sequence of events, each with an id, so a client watching the run can disconnect and resume later from the last id it saw.", "links": [{"label": "Technique: resumable event streams", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/resumable-events"}]}, "model": {"d": "The model is called for one turn at a time — one plan-and-decide step — with no memory of its own between calls; all continuity comes from what the worker feeds it, not from the model holding state."}, "worker": {"d": "The agent loop worker is stateless by design: it holds nothing in memory that matters if it dies. Everything that needs to survive a crash is written somewhere durable — the transcript, the environment — not kept only in the worker's process.", "links": [{"label": "Technique: stateless loop, stateful environment", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/stateless-loop"}]}, "transcript": {"d": "The transcript is a durable, append-only record of every turn the agent has taken, written as checkpoints. It is what lets a replacement worker figure out exactly where a crashed one left off.", "links": [{"label": "Technique: transcript checkpoint every turn", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/transcript-checkpoint"}]}, "env": {"d": "The environment is the sandbox or external provider where real state actually lives — files, running processes, open connections — the state the stateless worker doesn't hold itself."}, "w2": {"d": "The replacement worker is a new, identical worker that takes over after the original crashes. It doesn't need to know anything about the crash; it reads the transcript and reattaches to the environment as if it had been running the whole time."}, "snap": {"d": "Snapshots are periodic captures of the environment's actual state, not just the transcript of decisions, taken every N turns so a replacement worker can restore real state, not just replay the log of intentions, after a failure.", "links": [{"label": "Technique: environment snapshots", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/env-snapshots"}]}}, "edges": {"queue>worker": {"d": "A worker claims a task by taking a lease on it from the queue."}, "worker>model": {"d": "The worker calls the model for exactly one turn at a time, feeding it whatever context it needs for that turn."}, "worker>env": {"d": "The worker's tool calls act on the environment, which is where real state actually lives."}, "env>snap": {"d": "The environment's state is periodically captured into a snapshot."}, "worker>transcript": {"d": "Every turn the worker completes is checkpointed to the transcript before moving to the next one."}, "worker>stream": {"d": "The worker emits events to the stream as it works, each with an id a client can resume from."}, "transcript>w2": {"d": "After a crash, a replacement worker reads the transcript to find exactly which turn to resume from."}, "w2>env": {"d": "The replacement worker reattaches to the same environment the original worker was using."}, "snap>w2": {"d": "The replacement worker restores the environment's real state from the most recent snapshot, rather than starting from nothing."}}, "walk": ["queue", "queue>worker", "worker", "worker>model", "model", "worker>env", "env", "env>snap", "snap", "worker>transcript", "transcript", "worker>stream", "stream", "transcript>w2", "w2", "w2>env", "snap>w2"]},
  "sd:agent-safety:from-proposal-to-effect": {"nodes": {"model": {"d": "The planner model decides what to do next and proposes a tool call — it doesn't act directly; every proposal has to pass through the checks around it."}, "budget": {"d": "The budget guard caps how much the agent can spend on this run: steps, tokens, repeated identical calls. It's checked on every step, independent of what the step actually does, to stop runaway loops before they burn cost or time.", "links": [{"label": "Technique: budget caps and loop detection", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/budgets"}]}, "schema": {"d": "Schema check validates that a proposed tool call has the right shape — typed arguments, required fields present — before anything downstream considers whether the call should even be allowed."}, "reader": {"d": "The quarantined reader is a separate model instance that reads untrusted text (an email, a web page, a document) and extracts only specific fields, never full free text, back to the planner. This is the boundary that keeps instructions hidden in untrusted text from reaching the planner as if they were legitimate commands.", "links": [{"label": "Technique: prompt-injection defenses", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/injection"}]}, "human": {"d": "The user is asked to confirm or clarify before a risky action proceeds. This is the point where the system explicitly hands control back to a person rather than deciding alone.", "links": [{"label": "Technique: human confirmation and undo windows", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/hitl-undo"}]}, "policy": {"d": "The policy gate looks at a validated call's effect class (read, reversible, irreversible) and any taint from untrusted input, and decides: allow it, or ask a human first. It is the single deterministic checkpoint between 'the model wants to do this' and 'this actually happens.'", "links": [{"label": "Technique: deterministic policy gate", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/policy-gate"}]}, "exec": {"d": "The executor is what actually performs an allowed action, running with a scoped token and inside a sandbox — it has only the permissions the specific action needs, not the planner's full reach.", "links": [{"label": "Technique: least privilege and sandboxing", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/least-privilege"}]}, "ledger": {"d": "The effect ledger records every action the executor took, forming an audit trail and, for reversible actions, an undo window during which the effect can still be rolled back."}, "world": {"d": "External systems are the real things being acted on — mail, repositories, third-party APIs — the boundary where an agent's actions stop being simulated and start having consequences."}}, "edges": {"model>schema": {"d": "Every proposed tool call goes to schema validation first, regardless of what it does."}, "model>budget": {"d": "Every step the planner takes, whether or not it results in a tool call, counts against the budget guard's caps."}, "reader>model": {"d": "The quarantined reader only ever passes structured fields back to the planner, never the raw untrusted text it read."}, "schema>policy": {"d": "A call that passes schema validation moves to the policy gate for a decision on whether it's allowed to run."}, "policy>human": {"d": "When the policy gate flags a call as needing confirmation, control passes to the user before anything executes."}, "policy>exec": {"d": "When the policy gate allows a call outright, it goes straight to the executor."}, "exec>world": {"d": "The executor is the only node that actually touches the outside world — mail servers, repositories, third-party APIs."}, "exec>ledger": {"d": "Every executed action is recorded in the effect ledger, whether or not it required confirmation."}}, "walk": ["model", "model>schema", "schema", "model>budget", "budget", "reader", "reader>model", "schema>policy", "policy", "policy>human", "human", "policy>exec", "exec", "exec>world", "world", "exec>ledger", "ledger"]},
  "sd:alfred:alfred-high-level-design": {"nodes": {"sms": {"d": "The user texting alfred_ on its Linq phone number, one of three ways they can reach it."}, "web": {"d": "The user in the web or mobile app, built on Next.js and Flutter, talking to alfred_ over a live streamed connection instead of SMS."}, "claude": {"d": "Claude Desktop or Claude Code, connected to alfred_ as an MCP server, giving a Claude client the same tools alfred_ uses internally, over an API token instead of a user login."}, "mailin": {"d": "A dedicated inbound email address the user can reply to, so a request can start over email and alfred_ answers there too."}, "v6": {"d": "The conversation engine behind SMS: the ingress, jobs, turn pipeline shown in detail in the one-chat-turn diagram."}, "v6web": {"d": "The web equivalent of conv-v6, authenticated by JWT instead of a phone number, streaming the reply back over SSE instead of sending a text."}, "mcp": {"d": "Executes an MCP tool call as the specific user whose token it arrived on, against an allowlist of what an external MCP client is permitted to call.", "links": [{"label": "Pattern: least privilege and sandboxing", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/least-privilege"}]}, "tools": {"d": "The single tool registry every entry point, SMS, web, MCP, calls into, so a tool behaves the same no matter which surface invoked it."}, "prompt": {"d": "Builds the prompt for a turn from shared blocks, the first of which is common across the whole fleet of surfaces rather than rebuilt per entry point.", "links": [{"label": "Pattern: prompt caching", "url": "SYSTEM%20DESIGN.html#/patterns/llm-cost/prompt-cache"}]}, "models": {"d": "The model call boundary across providers: Anthropic and OpenAI models are both reachable through the same registry, so a tool doesn't need to know which one answered.", "links": [{"label": "Pattern: model routing and tiering", "url": "SYSTEM%20DESIGN.html#/patterns/llm-cost/routing"}]}, "pg": {"d": "The one database behind everything: row-level security scopes every query to its user, pg_cron drives every scheduled job, and pgmq is the message queue backing the event bus."}, "prov": {"d": "The real mail, calendar, and video providers alfred_ reads from and acts on."}, "ingest": {"d": "The push webhooks and poller that bring new mail and calendar events into the system, detailed in the background-pipeline diagram."}, "triage": {"d": "Classifies a staged email and decides how autonomously to act on it, after deterministic rules get first refusal.", "links": [{"label": "Session: your story, the alfred_ eval bench", "url": "index.html#/w/2"}]}, "act": {"d": "Carries out silent actions and writes draft replies once triage has decided what should happen to an email."}, "notify": {"d": "Texts the user about anything that needs attention, and sends an approved draft, but only after the user has said yes.", "links": [{"label": "Pattern: human confirmation and undo windows", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/hitl-undo"}]}, "briefs": {"d": "Scheduled jobs that assemble a summary of what's going on, a working-memory brief, a daily briefing, rather than answering a single question."}, "follow": {"d": "Tracks things alfred_ or the user said would happen later, promises made in a conversation, things being waited on, and surfaces them again when due."}, "routines": {"d": "Runs recurring, scheduled workflows the user has set up, on a cron trigger rather than in response to a message.", "links": [{"label": "Pattern: durable workflow engine", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/workflow-engine"}]}, "eval": {"d": "Scans production turn traces for likely failures and turns them into eval cases, so the same bug becomes a regression test instead of just a bad memory.", "links": [{"label": "Pattern: eval suites as release gates", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/eval-gate"}]}, "ctrl": {"d": "Configuration that controls rollout percentages and which model version handles which traffic, read live by ingestion and triage rather than baked into a deploy."}, "ops": {"d": "Tracks system health and model spend, and turns either one into an alert when something looks wrong.", "links": [{"label": "Pattern: monitoring and completeness checks", "url": "SYSTEM%20DESIGN.html#/patterns/reliability/monitoring"}]}, "slack": {"d": "The channels alerts and briefs actually go out through, whichever fits the audience: Slack for the team, email via Resend, SMS via Linq."}}, "edges": {"sms>v6": {"d": "An SMS message arrives as a Linq webhook into conv-v6."}, "web>v6web": {"d": "A web or mobile request authenticates with a JWT and gets a streamed SSE reply."}, "claude>mcp": {"d": "Claude connects to mcp-exec using an API token instead of a user session."}, "mailin>notify": {"d": "An email reply from alfred_ is sent back out through the same channel notify and send uses."}, "v6>tools": {"d": "conv-v6 calls into the shared tool registry."}, "v6web>tools": {"d": "conv-v6-web calls into the same shared tool registry."}, "mcp>tools": {"d": "mcp-exec calls into the same shared tool registry too."}, "v6>prompt": {"d": "conv-v6 builds its prompt through the shared prompt builder."}, "prompt>models": {"d": "The prompt is sent to the model registry, structured so its prefix can be cached."}, "tools>models": {"d": "Tool results feed back into the agent loop's next model call."}, "tools>prov": {"d": "A tool call reads from or writes to the real provider."}, "tools>pg": {"d": "A tool call is logged to Postgres as a trace and an effect."}, "prov>ingest": {"d": "New provider data arrives through the ingestion pipeline, pushed or pulled."}, "ingest>triage": {"d": "Ingested email is staged, then handed to triage."}, "triage>act": {"d": "Triage's decisions become pending actions for the executor and worker."}, "act>prov": {"d": "The executor writes actions like archiving or labeling back to the real provider."}, "act>notify": {"d": "A drafted reply or an important email is handed to notify and send."}, "notify>sms": {"d": "The user is notified over SMS."}, "triage>pg": {"d": "Triage's own decisions and category are persisted to Postgres."}, "pg>briefs": {"d": "A scheduled job in Postgres triggers brief generation."}, "pg>follow": {"d": "A scheduled job triggers the follow-up worker."}, "pg>routines": {"d": "A scheduled job triggers a user's routine."}, "briefs>notify": {"d": "A generated brief is sent out through notify and send."}, "ctrl>ingest": {"d": "The control plane's rollout percentage decides how much traffic ingestion processes through a given path."}, "ctrl>triage": {"d": "The control plane decides which model version triage uses for a slice of traffic."}, "pg>eval": {"d": "Turn traces stored in Postgres feed the eval scanner."}, "eval>ops": {"d": "The eval scanner's findings are digested into the monitoring system."}, "ops>slack": {"d": "An alert from monitoring goes out to Slack."}, "models>ops": {"d": "Every model call reports its usage to spend tracking."}}, "walk": ["sms", "sms>v6", "v6", "v6>tools", "tools", "v6>prompt", "prompt", "prompt>models", "models", "tools>models", "tools>prov", "prov", "tools>pg", "pg", "web", "web>v6web", "v6web", "v6web>tools", "claude", "claude>mcp", "mcp", "mcp>tools", "mailin", "mailin>notify", "prov>ingest", "ingest", "ingest>triage", "triage", "triage>act", "act", "act>prov", "act>notify", "notify", "notify>sms", "triage>pg", "ctrl", "ctrl>ingest", "ctrl>triage", "pg>briefs", "briefs", "briefs>notify", "pg>follow", "follow", "pg>routines", "routines", "pg>eval", "eval", "eval>ops", "ops", "ops>slack", "slack", "models>ops"]},
  "sd:alfred:background-pipeline-dana-mail-in-actions": {"nodes": {"prov": {"d": "The user's actual mailbox providers. alfred_ never stores their inbox wholesale; it watches it and acts back on it through these APIs."}, "push": {"d": "Five small webhook functions, one family, that receive a provider's push notification the moment a new email arrives, rather than waiting for a poll."}, "pull": {"d": "A scheduled poller that lists what changed since the last check, for accounts where a push notification isn't available or was missed. It's the fallback path into the same staging table push writes to.", "links": [{"label": "Pattern: polling and long polling", "url": "SYSTEM%20DESIGN.html#/patterns/real-time/polling"}]}, "bus": {"d": "A Postgres-native message queue: the webhook publishes an email.received event here instead of processing it inline, so a burst of mail doesn't overload the request that received it.", "links": [{"label": "Pattern: queue buffering", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-writes/queue-buffer"}]}, "cons": {"d": "Reads events off the bus, decides whether this email is even worth fetching the full body for, and if so, pulls it from the provider and stages it."}, "stage": {"d": "The staging table every ingested email lands in, written as an upsert keyed so processing the same email twice, a redelivered webhook, a poller overlap, doesn't create a duplicate.", "links": [{"label": "Pattern: idempotency keys", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/idempotency"}]}, "rules": {"d": "Simple, deterministic rules (sender, subject pattern) that can decide an email's fate without ever calling a model. A rule match short-circuits triage entirely.", "links": [{"label": "Pattern: deterministic policy gate", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/policy-gate"}]}, "triage": {"d": "The model call that classifies a staged email and decides how autonomously alfred_ is allowed to act on it: archive silently, draft a reply, or just notify the user."}, "pend": {"d": "One row per email, recording what triage decided should happen next. Nothing acts directly off the triage call; it always goes through this table first, so the pipeline can be resumed, audited, or reversed."}, "exec": {"d": "Carries out the low-risk actions triage marked safe to do without asking: archiving, labeling, moving an email."}, "draft": {"d": "The model call that actually writes the reply text for an email triage flagged as needing a drafted response, which then waits for the user before it's sent."}, "notify": {"d": "Texts the user when triage decided something needs their attention: an important email, or just an FYI, without necessarily asking them to act."}, "send": {"d": "The gate that actually sends a drafted reply: it only fires once the user has approved it, never on the model's own authority.", "links": [{"label": "Pattern: human confirmation and undo windows", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/hitl-undo"}]}, "user": {"d": "The person alfred_ works for, who approves drafts before they go out and receives notifications about what needs attention."}, "rev": {"d": "Can undo an action alfred_ took, and separately checks that an action actually had the effect it was supposed to have, a label really got applied, not just logged as applied.", "links": [{"label": "Pattern: idempotent tools and unknown results", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/unknown-results"}]}, "mon": {"d": "Periodically samples the provider's mailbox and compares it against what's in staging, to catch emails the ingestion path silently missed rather than finding out from the user.", "links": [{"label": "Pattern: monitoring and completeness checks", "url": "SYSTEM%20DESIGN.html#/patterns/reliability/monitoring"}]}}, "edges": {"prov>push": {"d": "The provider pushes a notification the moment something changes in the mailbox."}, "pull>prov": {"d": "The poller asks the provider what changed since it last checked."}, "push>bus": {"d": "A webhook publishes an email.received event to the bus instead of handling it inline."}, "bus>cons": {"d": "The staging consumer picks up events from the bus, gated by a rollout percentage so a change can be tested on a fraction of traffic."}, "cons>stage": {"d": "The consumer writes the fetched email into staging as an idempotent upsert."}, "pull>stage": {"d": "The poller writes directly into staging too, through the same idempotent upsert."}, "stage>triage": {"d": "Staged emails are handed to triage in batches, not one at a time."}, "rules>triage": {"d": "A deterministic rule is checked before the model call; a match skips triage's own judgment."}, "triage>pend": {"d": "Triage's decision for each email becomes one row in pending actions, never an immediate side effect."}, "pend>exec": {"d": "A pending action marked safe to execute silently goes to the action executor."}, "pend>draft": {"d": "A pending action that needs a reply drafted goes to donna-worker."}, "pend>notify": {"d": "A pending action that just needs the user informed goes to the notifier."}, "exec>prov": {"d": "The executor's action, archive, label, move, is written back to the real mailbox."}, "notify>user": {"d": "The user receives the notification by text."}, "user>send": {"d": "The user approves a drafted reply before it can be sent."}, "send>prov": {"d": "The approved draft is sent to the provider exactly once."}, "rev>pend": {"d": "The reverser can undo a pending action's effect, or verify it actually took hold."}, "mon>stage": {"d": "The completeness monitor samples staging against the provider to catch anything ingestion missed."}}, "walk": ["prov", "prov>push", "push", "push>bus", "bus", "bus>cons", "cons", "cons>stage", "pull", "pull>prov", "pull>stage", "stage", "rules", "rules>triage", "stage>triage", "triage", "triage>pend", "pend", "pend>exec", "exec", "exec>prov", "pend>draft", "draft", "user", "pend>notify", "notify", "notify>user", "user>send", "send", "send>prov", "rev", "rev>pend", "mon", "mon>stage"]},
  "sd:alfred:one-chat-turn-sms-shown-web-and-mcp-ente": {"nodes": {"linq": {"d": "The SMS provider alfred_ uses; every inbound text arrives here as a signed webhook, and every outbound reply goes back out through it."}, "ing": {"d": "Verifies the webhook's HMAC signature, drops anything already seen, a provider redelivery, and persists the inbound message before doing anything else with it.", "links": [{"label": "Pattern: idempotency keys", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/idempotency"}]}, "jobs": {"d": "A Postgres table used as a job queue: a worker claims the next unhandled turn with SELECT ... FOR UPDATE SKIP LOCKED, so two workers can never grab the same turn.", "links": [{"label": "Pattern: queue claiming with SKIP LOCKED", "url": "SYSTEM%20DESIGN.html#/patterns/contention/claim-skip-locked"}, {"label": "Session: backend depth, where a technical round goes down", "url": "index.html#/w/8"}]}, "turn": {"d": "Owns one chat turn end to end: it leases the job, opens a trace, assembles context, and runs the agent loop. Everything the user sees as one reply happens under this."}, "prompt": {"d": "Builds the prompt from four blocks, system instructions, memory, tools, conversation, with three deliberate cache breakpoints, so a fresh turn can reuse the model's cached prefix instead of reprocessing it.", "links": [{"label": "Pattern: prompt caching", "url": "SYSTEM%20DESIGN.html#/patterns/llm-cost/prompt-cache"}]}, "loop": {"d": "The agent's think-act loop for this turn, hard-capped at 12 steps so a confused plan can't run forever.", "links": [{"label": "Pattern: budget caps and loop detection", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/budgets"}]}, "model": {"d": "The actual model tier used for a given step, chosen by cost and difficulty: haiku for cheap classification-style steps, sonnet as the default, opus when the step needs it.", "links": [{"label": "Pattern: model routing and tiering", "url": "SYSTEM%20DESIGN.html#/patterns/llm-cost/routing"}]}, "wrap": {"d": "Every tool call passes through a stack of composed wrapper functions before it runs: a capability gate, a preview/confirm step for risky actions, and replay support for testing.", "links": [{"label": "Pattern: tool effect classes", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/effect-classes"}]}, "tools": {"d": "The single registry of every tool the agent can call, shared across every surface, SMS, web, MCP, so a tool's behavior doesn't drift between entry points."}, "prov": {"d": "The real external services a tool call ultimately reads from or writes to."}, "guards": {"d": "A final check on the model's draft reply before it goes out: catches unsupported claims or fabricated details that don't trace back to anything the tools actually returned.", "links": [{"label": "Pattern: explicit refusal paths", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/refusal"}]}, "trace": {"d": "A record of the whole turn: what was retrieved, what the model said at each step, what tools ran. Opened when the turn starts and closed when it ends.", "links": [{"label": "Pattern: transcript checkpoint every turn", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/transcript-checkpoint"}]}, "texec": {"d": "A log of every tool call the turn made, paired with a ledger of the real-world effects those calls had, so it's possible to answer exactly what alfred_ did, not just what it said it did."}, "out": {"d": "Applies a tone filter to the guarded reply, then sends it back out over Linq."}, "msgs": {"d": "The conversation history table: both the inbound message and the assistant's reply get a row here, which is what the next turn's prompt is built from."}}, "edges": {"linq>ing": {"d": "Linq expects a fast 200 response; ingress acknowledges immediately and processes the turn asynchronously."}, "ing>jobs": {"d": "Ingress enqueues a job to process this turn."}, "ing>msgs": {"d": "Ingress writes the inbound message as a row before the turn is even claimed."}, "jobs>turn": {"d": "A worker claims the job and starts the turn."}, "turn>prompt": {"d": "The turn assembles the four context blocks for the prompt builder."}, "prompt>model": {"d": "The built prompt is sent to the model, structured so its cached prefix can be reused."}, "turn>loop": {"d": "The turn runs the bounded agent loop."}, "loop>model": {"d": "Each step of the loop calls the model."}, "loop>wrap": {"d": "A tool_use response from the model is routed through the composed wrappers."}, "wrap>tools": {"d": "The wrappers, once satisfied, call into the tool registry."}, "tools>prov": {"d": "The tool executes against the real provider."}, "wrap>texec": {"d": "The wrapper logs the call and its effect to the executions and effects ledger."}, "loop>guards": {"d": "Before the loop's final answer is returned, it passes through the turn guards."}, "turn>trace": {"d": "The turn opens a trace record at the start and closes it at the end; one edge stands in for both events."}, "guards>out": {"d": "Text that passes the guards becomes the outbound message."}, "out>msgs": {"d": "The outbound reply is written as the assistant's row in message history."}, "out>linq": {"d": "The outbound reply is sent back out through Linq."}}, "walk": ["linq", "linq>ing", "ing", "ing>msgs", "msgs", "ing>jobs", "jobs", "jobs>turn", "turn", "turn>trace", "trace", "turn>prompt", "prompt", "prompt>model", "model", "turn>loop", "loop", "loop>model", "loop>wrap", "wrap", "wrap>tools", "tools", "tools>prov", "prov", "wrap>texec", "texec", "loop>guards", "guards", "guards>out", "out", "out>msgs", "out>linq"]},
  "sd:alfred:what-one-tool-call-passes-through": {"nodes": {"m": {"d": "The model's tool_use response for one action: the tool name and its arguments, before anything has been checked or run."}, "s": {"d": "Validates the model's tool_use arguments against a fixed schema before anything else happens, catching a malformed or invented field immediately."}, "c": {"d": "Checks whether this call is even the kind of thing this tool is allowed to do: a plain read, a write, or a bulk operation, each held to a different bar.", "links": [{"label": "Pattern: tool effect classes", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/effect-classes"}]}, "p": {"d": "For anything risky enough to require it, shows the user what the call would do and waits for their explicit confirmation before continuing.", "links": [{"label": "Pattern: human confirmation and undo windows", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/hitl-undo"}]}, "i": {"d": "Attaches an idempotency key so that if this call is retried, a timeout, a crash, replaying it doesn't repeat the real-world effect twice.", "links": [{"label": "Pattern: idempotency keys", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/idempotency"}]}, "x": {"d": "Actually runs the call against the real tool, under a timeout, so a hung provider doesn't hang the whole turn."}, "l": {"d": "Records that the call happened and what effect it had, the ledger that answers what alfred_ actually did, independent of what it said."}, "e": {"d": "Turns the result of the call into a reference the next turn's context can use, so the agent can say 'that email' instead of re-fetching it."}, "u": {"d": "The person who has to say yes before a call gated behind preview and confirm is allowed to proceed."}}, "edges": {"m>s": {"d": "The model's raw tool_use block is checked against its schema first."}, "s>c": {"d": "A schema-valid call is checked against the capability gate."}, "c>p": {"d": "A call the capability gate allows moves to the preview and confirm step."}, "p>u": {"d": "The user is shown a preview of what the call would do."}, "u>p": {"d": "The user's confirmation comes back to the preview step."}, "p>i": {"d": "A confirmed, or no-confirmation-needed, call gets an idempotency key."}, "i>x": {"d": "The call is executed, keyed so a retry can't repeat its effect."}, "x>l": {"d": "The execution result is logged along with its effect."}, "l>e": {"d": "The logged result is turned into an entity reference for the next turn."}}, "walk": ["m", "m>s", "s", "s>c", "c", "c>p", "p", "p>u", "u", "u>p", "p>i", "i", "i>x", "x", "x>l", "l", "l>e", "e"]},
  "sd:async-job": {"nodes": {"client": {"d": "The caller making the original request.\n\nIt gets an id back almost immediately and is expected to check back later rather than wait on the connection."}, "api": {"d": "The endpoint that validates the request, enqueues the actual work, and responds with HTTP 202 and a job id before the work is done.\n\n202 Accepted specifically signals 'received, not yet complete' — a deliberate contrast to 200 OK, which would imply the work already finished."}, "queue": {"d": "Where the actual job waits until a worker is free to run it.\n\nThe API doesn't wait on this queue at all; enqueuing is fire-and-forget from its point of view.", "links": [{"label": "What consumes this queue: queue plus worker pool", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/worker-pool"}]}, "status": {"d": "A record, keyed by the job id, that tracks the job from queued through to done, or failed.\n\nThis is what the client polls using the id it got back from the 202 response."}}, "edges": {"client>api": {"d": "The client makes its original request."}, "api>client": {"d": "The API responds immediately with 202 and a job id, without waiting for the work to run."}, "api>queue": {"d": "In parallel with responding to the client, the API enqueues the actual job."}, "client>status": {"d": "The client polls the status endpoint, asynchronously and independently of the original request, using the job id."}}, "walk": ["client", "client>api", "api", "api>client", "api>queue", "queue", "client>status", "status"]},
  "sd:atomic": {"nodes": {"a": {"d": "Buyer A, issuing a conditional UPDATE against the seat row.\n\nNo lock is taken beforehand — the database's own atomicity is what decides the race."}, "b": {"d": "Buyer B, issuing the identical conditional UPDATE at nearly the same time.\n\nWhichever of A's or B's UPDATE the database applies first changes the row's state, which makes the other's WHERE clause stop matching."}, "db": {"d": "The seat row, updated only `WHERE status = 'available'`.\n\nThe database applies concurrent UPDATEs to the same row one at a time internally, so exactly one of two identical conditional writes can match and take effect — there is no window where both could succeed."}}, "edges": {"a>db": {"d": "A's UPDATE matches the WHERE clause first, changes one row, and wins the seat."}, "b>db": {"d": "By the time B's identical UPDATE runs, the row no longer has `status = 'available'`, so it matches zero rows — B's client sees 0 rows affected and knows it lost."}}, "walk": ["a", "b", "a>db", "b>db", "db"]},
  "sd:batch-parallel": {"nodes": {"jobs": {"d": "Tool calls here are independent of each other — none needs another's result — which is what makes them safe to run out of order or at the same time instead of one after another."}, "parallel": {"d": "Fan out runs the independent calls concurrently, on the normal synchronous API, so wall-clock time is close to the slowest single call instead of the sum of all of them."}, "batch": {"d": "The batch API queues calls together and processes them asynchronously, off the interactive path, at a lower per-token price than the synchronous API, in exchange for not knowing exactly when a result comes back.", "links": [{"label": "Lesson: caching and cost", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/11-llm-engineering/11-caching-cost"}]}, "model": {"d": "Model calls here are the same underlying model, reached through two different paths — the fast concurrent path or the slow, cheaper batch path."}}, "edges": {"jobs>parallel": {"d": "When a result is needed soon, the independent calls are fanned out to run concurrently."}, "parallel>model": {"d": "The concurrent calls hit the model at the same time, each independently."}, "jobs>batch": {"d": "When there's no rush, the same independent calls are queued into the batch API instead."}, "batch>model": {"d": "Batched calls reach the model asynchronously, often hours after being submitted, at a lower price."}}, "walk": ["jobs", "jobs>parallel", "parallel", "parallel>model", "jobs>batch", "batch", "batch>model", "model"]},
  "sd:batching": {"nodes": {"writer": {"d": "Issuing what looks like a single small write, an increment, say, but is really being accumulated rather than applied immediately."}, "buffer": {"d": "Holds writes in memory, accumulating them instead of hitting the database on every single one."}, "db": {"d": "Receives the buffer's accumulated writes on a fixed schedule, here every ten seconds, as one batched operation instead of many small ones."}}, "edges": {"writer>buffer": {"d": "A write is accumulated into the buffer rather than applied immediately."}, "buffer>db": {"d": "The buffer flushes to the database on a fixed timer, not on every individual write."}}, "walk": ["writer", "writer>buffer", "buffer", "buffer>db", "db"]},
  "sd:budgets": {"nodes": {"loop": {"d": "The agent loop is the ongoing cycle of the agent proposing a step, taking an action, and deciding what to do next, with no built-in sense of when to stop on its own."}, "check": {"d": "The budget guard checks every single step against caps — total steps, total tokens, and whether the same call is repeating — before letting the loop continue. It runs on every step, not just occasionally, because a runaway loop can burn through budget in seconds."}, "continue": {"d": "Next step is what happens when the check finds nothing wrong: the loop proceeds normally."}, "stop": {"d": "Halt is triggered by hitting a hard cap, or by a specific pattern this diagram calls out: the same call repeated three times, a strong signal the agent is stuck rather than making progress.", "links": [{"label": "Lesson: cost governors", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/15-autonomous-systems/13-cost-governors"}, {"label": "Lesson: kill switches and canaries", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/15-autonomous-systems/14-kill-switches-canaries"}]}}, "edges": {"loop>check": {"d": "Every step of the agent loop is checked against the budget guard before it's allowed to proceed."}, "check>continue": {"d": "A step within all limits is allowed to continue normally."}, "check>stop": {"d": "A step that exceeds a cap, or that repeats the same call for the third time, halts the loop instead of continuing."}}, "walk": ["loop", "loop>check", "check", "check>continue", "continue", "check>stop", "stop"]},
  "sd:builtin": {"nodes": {"app": {"d": "App is any application code issuing a location query, with no spatial-indexing logic of its own."}, "db": {"d": "PostGIS is the geospatial extension for Postgres; ST_DWithin is its indexed radius-search function, doing in one query what the other geo techniques build by hand."}}, "edges": {"app>db": {"d": "The app issues a single query with a radius; PostGIS handles the rest with a spatial index (Redis GEO and Elasticsearch offer the same kind of built-in radius query)."}}, "walk": ["app", "app>db", "db"]},
  "sd:bulkhead": {"nodes": {"reqs": {"d": "Requests is incoming traffic of at least two different kinds, sharing nothing downstream by design."}, "poolA": {"d": "Pool A is a resource pool, workers, connections, or quota, reserved exclusively for one kind of traffic (here, chat) so it can't be starved by another kind."}, "poolB": {"d": "Pool B is a separate, isolated pool for a different kind of traffic (here, batch); its resources are untouchable by whatever happens in pool A."}, "depA": {"d": "Dependency A is stuck and has drained pool A's capacity entirely: every worker in that pool is waiting on a dependency that isn't responding."}, "depB": {"d": "Dependency B is healthy and unaffected, and pool B keeps serving normally because it never shared resources with pool A.", "links": [{"label": "Design: coding-agent caps concurrent sandboxes per organization", "url": "SYSTEM%20DESIGN.html#/designs/coding-agent/patterns"}]}}, "edges": {"reqs>poolA": {"d": "Chat traffic is routed into its own dedicated pool."}, "reqs>poolB": {"d": "Batch traffic is routed into a separate pool, isolated from chat's."}, "poolA>depA": {"d": "Pool A's entire quota is exhausted waiting on its stuck dependency, but the damage is contained to pool A."}, "poolB>depB": {"d": "Pool B keeps calling its own healthy dependency and keeps serving, unaware anything is wrong elsewhere."}}, "walk": ["reqs", "reqs>poolA", "poolA", "poolA>depA", "depA", "reqs>poolB", "poolB", "poolB>depB", "depB"]},
  "sd:cache-aside": {"nodes": {"app": {"d": "Reads by checking the cache before ever touching the database."}, "cache": {"d": "Holds a copy of recently-read data, with every key given a TTL so a cache that's fallen out of sync still self-corrects eventually."}, "db": {"d": "The actual source of truth. It's only read on a cache miss, and every value read from it is used to refill the cache."}}, "edges": {"app>cache": {"d": "The app checks the cache first."}, "app>db": {"d": "On a miss, the app reads from the database directly."}, "db>cache": {"d": "The value just read from the database is written into the cache for next time."}}, "walk": ["app", "app>cache", "cache", "app>db", "db", "db>cache"]},
  "sd:cdc": {"nodes": {"db": {"d": "Database is the source of truth; nothing here is derived, every other node in this diagram exists because of what happens to this one."}, "log": {"d": "Change log is an ordered, durable record of every change to the database, which is what CDC actually taps into rather than the application's own write path."}, "cache": {"d": "Cache is a derived store that gets evicted, not updated, when the log shows the underlying row changed."}, "index": {"d": "Search index is a derived store that gets updated to reflect the change, kept in sync by tailing the same log the cache uses.", "links": [{"label": "Design: ticketmaster flows Postgres changes to Elasticsearch through CDC", "url": "SYSTEM%20DESIGN.html#/designs/ticketmaster/patterns"}]}}, "edges": {"db>log": {"d": "Every change to the database is appended to its own change log, as a side effect of the write itself, not a separate action the application takes."}, "log>cache": {"d": "A consumer tails the log and evicts the corresponding cache key, asynchronously, some time after the actual write committed."}, "log>index": {"d": "A second consumer tails the same log and updates the search index, also asynchronously, and independent of the cache consumer."}}, "walk": ["db", "db>log", "log", "log>cache", "cache", "log>index", "index"]},
  "sd:cdn": {"nodes": {"client": {"d": "Whoever requests a page or asset."}, "cdn": {"d": "A cache at the network edge, close to the client, holding content for as long as the origin's cache-control TTL says it's valid."}, "origin": {"d": "The real server behind the CDN, only hit when the edge doesn't have a fresh copy, or when the origin proactively purges one."}}, "edges": {"client>cdn": {"d": "The client's request goes to the nearest CDN edge first."}, "cdn>origin": {"d": "On a cache miss, or an expired TTL, the edge fetches from the origin."}, "origin>cdn": {"d": "The origin can proactively purge a cached copy when the underlying content changes, rather than waiting for the TTL to expire."}}, "walk": ["client", "client>cdn", "cdn", "cdn>origin", "origin", "origin>cdn"]},
  "sd:cdn-signed": {"nodes": {"client": {"d": "Client is whatever is requesting the file: a browser, an app, or another service. It never talks to object storage directly; it only ever holds a URL."}, "cdn": {"d": "CDN edge is a caching layer close to the client that also enforces access control, checking a signature or token on the URL before serving anything. It is the only thing standing between a private object and the open internet, so revoking access is only as fast as that signature's expiry.", "links": [{"label": "Technique: cache-aside", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-reads/cache-aside"}]}, "storage": {"d": "Object storage holds the actual file, kept private so it can never be reached directly, only through the CDN."}}, "edges": {"client>cdn": {"d": "The client presents a URL that was signed (or a signed cookie) proving it is allowed to fetch this specific object before its expiry."}, "cdn>storage": {"d": "On a cache miss, the edge fetches the object from the private origin and caches it, so later requests for the same object don't repeat this fetch."}, "cdn>client": {"d": "The edge streams the (now cached) bytes back to the client."}}, "walk": ["client", "client>cdn", "cdn", "cdn>storage", "storage", "cdn>client"]},
  "sd:cells": {"nodes": {"client": {"d": "Client supplies a search radius that needs to be translated into a set of index lookups."}, "cover": {"d": "Cover radius takes that radius and computes the minimal set of hexagonal (or similar) cell ids that together cover the whole search area — this covering step is what's unique to hierarchical systems like S2 or H3."}, "c1": {"d": "Hex cell is one of the cells returned by the cover step; each cell is queried independently for candidates."}, "c2": {"d": "Hex cell (a second one) shows that covering a radius almost always spans more than one cell, since a search area rarely aligns to a single cell's boundary."}}, "edges": {"client>cover": {"d": "The radius to search is handed to the covering algorithm."}, "cover>c1": {"d": "One of the cells the radius overlaps is queried."}, "cover>c2": {"d": "A second overlapping cell is queried the same way — the radius is covered by however many cells it takes."}}, "walk": ["client", "client>cover", "cover", "cover>c1", "c1", "cover>c2", "c2"]},
  "sd:checkpointing": {"nodes": {"worker": {"d": "The process doing a long unit of work — long enough that losing all progress on a crash would be expensive.\n\nIt periodically pauses to record what it's done so far, rather than only reporting a result at the very end."}, "ckpt": {"d": "A durable record of the last completed unit of work — a batch number, a byte offset, a row id.\n\nIt only needs to capture enough to know where to pick back up, not the entire internal state of the worker.", "links": [{"label": "Same idea for an agent loop: transcript checkpointing", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/transcript-checkpoint"}]}, "restart": {"d": "A fresh process instance, started after the original worker crashed.\n\nInstead of restarting the job from the beginning, it reads the last checkpoint and continues from there."}}, "edges": {"worker>ckpt": {"d": "The worker periodically saves its progress before continuing."}, "worker>restart": {"d": "The worker crashes, asynchronously ending its own execution without cleanup."}, "ckpt>restart": {"d": "The new process reads the last saved checkpoint and resumes from there instead of from zero."}}, "walk": ["worker", "worker>ckpt", "ckpt", "worker>restart", "restart", "ckpt>restart"]},
  "sd:circuit-breaker": {"nodes": {"client": {"d": "Client is the caller making a request that may hit a failing dependency."}, "breaker": {"d": "Circuit breaker tracks recent failures for a dependency; once it opens, it stops calling that dependency at all and fails fast, even before a new call would itself time out.", "links": [{"label": "Design: email-agent trips a breaker on a failing provider instead of looping", "url": "SYSTEM%20DESIGN.html#/designs/email-agent/patterns"}]}, "dep": {"d": "Dependency is a service currently failing — the breaker's whole job is to stop sending it more load while it's in this state."}, "fallback": {"d": "Fallback is a fast, safe default returned instead of a real call, so an open breaker fails the request quickly rather than waiting out a timeout that would happen anyway."}}, "edges": {"client>breaker": {"d": "Every call to the dependency is routed through the breaker first, not made directly."}, "breaker>fallback": {"d": "While open, the breaker skips the dependency entirely and returns the fallback immediately."}, "breaker>dep": {"d": "Periodically, off the request path, the breaker probes the dependency directly to see if it has recovered, so it can close again."}}, "walk": ["client", "client>breaker", "breaker", "breaker>fallback", "fallback", "breaker>dep", "dep"]},
  "sd:citations": {"nodes": {"gen": {"d": "Generate produces a draft answer with inline citation markers — a marker after each claim pointing to which retrieved chunk supposedly supports it."}, "src": {"d": "Sources are the chunks that were actually retrieved for this answer, the only material a citation marker is allowed to point to."}, "verify": {"d": "Verify checks each citation marker against the source chunks: does the chunk it points to actually contain something that supports the claim next to it? A marker pointing to a chunk that doesn't back the claim fails this check.", "links": [{"label": "Provenance model behind a citation check", "url": "https://arxiv.org/html/2501.17887v1"}]}, "out": {"d": "The answer that reaches the caller keeps only claims whose citations passed verification; unsupported claims are dropped rather than shown with a false citation."}}, "edges": {"gen>verify": {"d": "The draft, with unchecked citation markers, is sent to verification before anything is shown."}, "src>verify": {"d": "The actual retrieved chunks are compared against each cited claim to confirm the citation is real."}, "verify>out": {"d": "Only claims with a citation that passed verification make it into the final answer."}}, "walk": ["gen", "src", "gen>verify", "src>verify", "verify", "verify>out", "out"]},
  "sd:claim-skip-locked": {"nodes": {"w1": {"d": "The first worker to poll the job table for available work.\n\nIt locks the row it selects as part of the same query, so no other worker can grab it too."}, "w2": {"d": "A second worker polling at the same time.\n\nBecause row A is already locked by w1, w2's query, written with `SKIP LOCKED`, simply skips over it and claims a different row instead of blocking or erroring."}, "table": {"d": "The job table, queried with `SELECT ... FOR UPDATE SKIP LOCKED` so concurrent workers never block each other and never claim the same row.\n\nThis gets the same 'exactly one worker per job' guarantee as a distributed lock, using ordinary database row locks instead of a separate locking service.", "links": [{"label": "Where this is used: queue plus worker pool", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/worker-pool"}, {"label": "Reading: FOR UPDATE SKIP LOCKED (Postgres docs)", "url": "https://www.postgresql.org/docs/current/sql-select.html"}]}}, "edges": {"w1>table": {"d": "Worker 1's query locks and returns row A in a single atomic step."}, "w2>table": {"d": "Worker 2's query, run concurrently, skips the already-locked row A and returns row B instead — no blocking, no collision."}}, "walk": ["w1", "w1>table", "table", "w2", "w2>table"]},
  "sd:coding-agent:cloud-coding-agent-high-level-design": {"nodes": {"client": {"d": "Wherever a task can be assigned from: a web UI, a Slack command, or a GitHub mention. All three just create a task; what happens next is identical regardless of where it came from."}, "api": {"d": "Accepts a new task, stores it in Postgres, and enqueues it for a worker to pick up. It is also where clients connect to watch a task's progress."}, "queue": {"d": "Holds tasks waiting for a worker, ordered by priority, and hands one out as a lease rather than a permanent assignment, so a worker that dies mid-task doesn't lose it forever.", "links": [{"label": "Pattern: leases, heartbeats, visibility timeouts", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/leases"}]}, "worker": {"d": "Runs the actual agent loop for one task: plan, call a tool, observe, repeat. The worker itself holds no state between turns; everything it needs to resume comes from the transcript store, which is what lets any worker pick up any task.", "links": [{"label": "Pattern: stateless loop, stateful environment", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/stateless-loop"}]}, "model": {"d": "The model call boundary for the agent loop, with prompt caching so the large, mostly-repeated system context isn't re-sent and re-billed on every turn.", "links": [{"label": "Pattern: prompt caching", "url": "SYSTEM%20DESIGN.html#/patterns/llm-cost/prompt-cache"}]}, "sandbox": {"d": "Isolated microVMs where the agent actually edits code and runs commands, kept in a warm pool so starting a new task doesn't wait on a cold boot. Nothing the agent runs here can reach anything outside its own VM.", "links": [{"label": "Pattern: least privilege and sandboxing", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/least-privilege"}]}, "snap": {"d": "Point-in-time copies of a sandbox's repository and filesystem state, so a task can resume from where it left off, or a bad state can be rolled back."}, "git": {"d": "The actual GitHub or GitLab the sandbox pushes a branch to and opens a pull request against, once the agent's work is ready for review."}, "events": {"d": "A per-task stream of progress events the worker emits as it goes, so a client watching the task sees live updates rather than polling for a final result.", "links": [{"label": "Pattern: resumable streams", "url": "SYSTEM%20DESIGN.html#/patterns/real-time/resumable"}]}, "transcript": {"d": "Every turn of the agent loop is checkpointed here: what it planned, what tool it called, what came back. This is what lets a stateless worker resume a task, and what an eval suite replays later.", "links": [{"label": "Pattern: transcript checkpoint every turn", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/transcript-checkpoint"}]}, "eval": {"d": "Replays checkpointed transcripts against real tasks with hidden tests, to check whether a change to the agent's prompt or model makes it better or worse before it ships to real users.", "links": [{"label": "Pattern: eval suites as release gates", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/eval-gate"}]}}, "edges": {"client>api": {"d": "A task is created from whichever client the user is in."}, "api>queue": {"d": "A new task is placed on the task queue."}, "queue>worker": {"d": "A worker leases the next task rather than owning it permanently."}, "worker>model": {"d": "The worker calls the model for each turn of the agent loop."}, "worker>sandbox": {"d": "The worker calls into the sandbox to run a tool: edit a file, run a command."}, "sandbox>snap": {"d": "The sandbox's filesystem state is snapshotted so the task can resume or roll back."}, "sandbox>git": {"d": "The sandbox pushes the finished branch and opens a pull request."}, "worker>transcript": {"d": "The worker checkpoints every turn to the transcript store."}, "worker>events": {"d": "The worker emits progress events as the task runs."}, "events>api": {"d": "The task API streams those events to a connected client over SSE."}, "transcript>eval": {"d": "Checkpointed transcripts are replayed by the offline eval suite."}}, "walk": ["client", "client>api", "api", "api>queue", "queue", "queue>worker", "worker", "worker>model", "model", "worker>sandbox", "sandbox", "sandbox>snap", "snap", "sandbox>git", "git", "worker>transcript", "transcript", "worker>events", "events", "events>api", "transcript>eval", "eval"]},
  "sd:consistency:one-source-of-truth-many-copies": {"nodes": {"writer": {"d": "Writer is whoever originates a change: a user action, a job, anything that produces a write."}, "svc": {"d": "Service commits the write as a single transaction against one place, the primary, before anything else in the diagram happens — this is what makes the primary the actual source of truth.", "links": [{"label": "Technique: strong versus eventual, per feature", "url": "SYSTEM%20DESIGN.html#/patterns/consistency/per-feature"}]}, "reader": {"d": "Reader is anyone reading data back, by default routed to a replica, unless it needs to see its own very recent write."}, "primary": {"d": "Primary DB is the single source of truth: every other store in this diagram, replica, cache, search index, is derived from it, directly or indirectly."}, "replica": {"d": "Replica is a copy of the primary kept in near-real-time sync, but it lags — reads sent here can be seconds behind the actual latest write."}, "relay": {"d": "CDC relay tails the primary's own change log and turns each row-level change into an event other systems can consume, without the application publishing anything itself.", "links": [{"label": "Technique: change data capture", "url": "SYSTEM%20DESIGN.html#/patterns/consistency/cdc"}]}, "bus": {"d": "Event log holds the change stream, ordered per key so consumers see changes to the same record in the order they actually happened."}, "cache": {"d": "Cache is a derived store, evicted whenever the underlying data changes — it never receives writes directly, only invalidations."}, "search": {"d": "Search index is a derived, eventually consistent copy of the data, optimized for search rather than for correctness under load; being seconds behind the primary is an accepted cost here."}}, "edges": {"writer>svc": {"d": "A change originates from the writer and reaches the service that will commit it."}, "svc>primary": {"d": "The write is committed to the primary as a single transaction; nothing is considered done until this succeeds."}, "primary>relay": {"d": "The primary's own change log is what the CDC relay reads, not a message the application sends explicitly."}, "relay>bus": {"d": "Every captured change is published onto the ordered event log."}, "bus>cache": {"d": "A change event tells the cache to evict the now-stale key, rather than trying to update it in place."}, "bus>search": {"d": "A change event tells the search index to re-index the changed record, asynchronously and after the primary's own write already succeeded."}, "primary>replica": {"d": "The primary replicates to the replica asynchronously, which is exactly why the replica can lag."}, "reader>replica": {"d": "By default, ordinary reads go to the replica: cheaper, but possibly stale."}, "reader>primary": {"d": "A reader who needs to see their own just-made write is routed to the primary instead, to guarantee read-your-writes."}}, "walk": ["writer", "writer>svc", "svc", "svc>primary", "primary", "primary>replica", "replica", "reader", "reader>replica", "reader>primary", "primary>relay", "relay", "relay>bus", "bus", "bus>cache", "cache", "bus>search", "search"]},
  "sd:consistent-hashing": {"nodes": {"a": {"d": "A node on the hash ring, holding whatever slice of the key space falls between it and its neighbor."}, "newnode": {"d": "A node just added to the ring. It claims one contiguous slice of key space from whichever node was previously responsible for that part of the ring, here node B, and nothing from any other node."}, "b": {"d": "The node the new node took a slice from. It keeps everything else; only the one slice moved."}, "c": {"d": "A node elsewhere on the ring, completely unaffected by the new node joining. This is the entire point of consistent hashing over plain hash(key) sharding: adding a node only disturbs its immediate neighbor."}}, "edges": {"a>newnode": {"d": "The new node sits on the ring between node A and node B."}, "newnode>b": {"d": "The new node claims its slice of key space from node B specifically."}, "b>c": {"d": "Node B and node C are ring neighbors, in the same order as before the new node joined."}}, "walk": ["a", "a>newnode", "newnode", "newnode>b", "b", "b>c", "c"]},
  "sd:contention:two-actors-one-resource": {"nodes": {"a": {"d": "One of two buyers racing for the same resource — here, seat 12, at nearly the same instant as buyer B.\n\nContention like this isn't rare: any high-demand release (concert tickets, a flash sale) produces exactly this shape."}, "b": {"d": "The second buyer, hitting the booking service for the identical seat within the same request window.\n\nOnly one of A and B can win; the diagram is really about which mechanism decides that correctly."}, "svc": {"d": "The booking service, which must guarantee that exactly one of the competing requests succeeds, regardless of timing.\n\nIt has two families of tools shown branching below it: take a lock or hold up front (pessimistic), or serialize through a queue; or skip locking and let a conditional database write decide (optimistic or atomic)."}, "lock": {"d": "A short-lived exclusive claim on the seat, acquired with something like `SET key NX PX ttl`, plus a fencing token so a holder that resumes after its lock has expired can't write anyway.\n\nThis is the app-level equivalent of a database row lock: nobody else can proceed until the holder releases it or the TTL runs out.", "links": [{"label": "Technique: distributed locks and leases with TTL", "url": "SYSTEM%20DESIGN.html#/patterns/contention/distributed-lock"}]}, "queue": {"d": "An alternative to locking: route every claim for this seat through one ordered queue, so requests are handled one at a time by construction, instead of racing.\n\nThere's nothing to detect or reject here — contention is avoided rather than resolved, because only one consumer ever touches this key.", "links": [{"label": "Technique: single writer per key", "url": "SYSTEM%20DESIGN.html#/patterns/contention/single-writer"}]}, "db": {"d": "The database row backing the seat, updated with a conditional write — a version check or a status check — so a concurrent second write is rejected instead of silently overwriting the first.\n\nThis is the mechanism behind both optimistic concurrency and a plain atomic conditional update; which one it is depends on whether the check is an explicit version column or a status flag.", "links": [{"label": "Technique: atomic conditional update", "url": "SYSTEM%20DESIGN.html#/patterns/contention/atomic"}, {"label": "Technique: optimistic concurrency (version check)", "url": "SYSTEM%20DESIGN.html#/patterns/contention/optimistic"}]}}, "edges": {"a>svc": {"d": "Buyer A's request arrives asking to claim seat 12."}, "b>svc": {"d": "Buyer B's request arrives for the same seat, close enough in time to race A."}, "svc>lock": {"d": "One strategy: acquire an exclusive hold on the seat before touching the database at all."}, "svc>db": {"d": "Another strategy: skip the lock and let a compare-and-swap write on the row itself decide the winner."}, "svc>queue": {"d": "A third strategy: instead of locking or racing, hand the claim to a queue that processes seat-12 requests strictly one at a time."}, "queue>db": {"d": "Once serialized by the queue, writes to the seat row happen in order, so there is nothing left to race."}}, "walk": ["a", "b", "a>svc", "b>svc", "svc", "svc>lock", "lock", "svc>db", "db", "svc>queue", "queue", "queue>db"]},
  "sd:context-budget": {"nodes": {"output": {"d": "Tool output is the raw result of something the system just did — a file read, a search, a database query — potentially far larger than a model needs or than its context window holds at reasonable cost. Ten thousand lines from a log dump is a realistic size for this node."}, "budget": {"d": "The budget guard decides how much of the raw output the model actually gets to see, by truncating, summarizing, or retrieving only the relevant slice.\n\nEvery token in the context window costs money and attention on every subsequent turn, so passing the full ten thousand lines forward would multiply that cost on every later step of the conversation, not just this one.", "links": [{"label": "Lesson: context engineering", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/11-llm-engineering/05-context-engineering"}]}, "model": {"d": "The model sees only the trimmed slice the budget guard decided was relevant, not the original raw output. Its answer quality now depends on the guard having kept the right part."}}, "edges": {"output>budget": {"d": "The full, untrimmed tool output is handed to the budget guard before the model ever sees it."}, "budget>model": {"d": "Only the trimmed, relevant slice reaches the model's context window."}}, "walk": ["output", "output>budget", "budget", "budget>model", "model"]},
  "sd:cross-service": {"nodes": {"hold": {"d": "The first step of a cross-service operation — holding a seat — completed locally in one service.\n\nUnlike a single-database transaction, there is no cross-service guarantee tying this step to the next; if something later fails, undoing this step is a separate, explicit action."}, "charge": {"d": "The second step, charging the buyer's card in a different service, which fails in this scenario.\n\nA true two-phase commit would need every participant to vote before anything commits; this diagram shows the alternative instead — proceed step by step and compensate afterward if something breaks."}, "release": {"d": "The compensating action that undoes the hold once the charge fails.\n\nThis is the core idea of a saga: instead of a distributed transaction that all commits or all rolls back atomically, each step has a matching undo, run explicitly when a later step fails.", "links": [{"label": "Technique: sagas with compensation", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/saga"}]}}, "edges": {"hold>charge": {"d": "Having held the seat, the process proceeds to the next step without waiting on any cross-service commit protocol."}, "charge>release": {"d": "When the charge fails, the failure triggers the hold's compensating action instead of leaving the seat stuck as held."}}, "walk": ["hold", "hold>charge", "charge", "charge>release", "release"]},
  "sd:degradation": {"nodes": {"client": {"d": "Client is whoever made the original request and receives whatever answer comes back, full or reduced."}, "svc": {"d": "Service tries the primary path first and only falls back if that path is unavailable — degrading is a deliberate choice here, not a crash."}, "dep": {"d": "Model API is the primary dependency, shown down — the diagram assumes it can be unavailable and designs around that instead of assuming it's always up."}, "fallback": {"d": "Human review is the fallback: a slower, different path (or a stale cache) used only when the primary dependency can't be reached, so the request still gets answered, just not the same way.", "links": [{"label": "Design: prior-auth routes cases to clinicians instead of waiting when the model gateway is down", "url": "SYSTEM%20DESIGN.html#/designs/prior-auth/patterns"}]}}, "edges": {"client>svc": {"d": "The request arrives expecting the normal, full-quality response."}, "svc>dep": {"d": "The service tries its usual dependency first; this attempt fails because the dependency is down."}, "svc>fallback": {"d": "On failure, the service deliberately switches to a reduced path instead of returning an error."}, "fallback>client": {"d": "The client receives an answer, but a visibly reduced one, a human-reviewed result instead of a model's, or a stale cached one."}}, "walk": ["client", "client>svc", "svc", "svc>dep", "dep", "svc>fallback", "fallback", "fallback>client"]},
  "sd:denormalize": {"nodes": {"writer": {"d": "Whatever is recording a new like: it does two things, not one."}, "likes": {"d": "The normalized table of individual like records, the source of truth for who liked what."}, "count": {"d": "A precomputed count kept on the post itself, updated whenever a like is added, so reading a like count is a single lookup instead of a COUNT(*) over the likes table."}, "reader": {"d": "Whatever displays the like count, which reads only the precomputed field, never the underlying likes table."}}, "edges": {"writer>likes": {"d": "A new like is inserted into the normalized likes table."}, "writer>count": {"d": "The writer also increments the precomputed count, as a second write."}, "reader>count": {"d": "A reader gets the count in one lookup, never scanning the likes table."}}, "walk": ["writer", "writer>likes", "likes", "writer>count", "count", "reader", "reader>count"]},
  "sd:distributed-lock": {"nodes": {"oldh": {"d": "The original lock holder, which paused for longer than the lease's TTL (a GC pause, a network partition, a slow disk) without realizing time had passed.\n\nIt still believes it holds the lock and will try to write using its old fencing token, 5 — the whole point of this diagram is making sure that write can't cause harm."}, "newh": {"d": "A new holder that acquired the lock only after the old holder's lease genuinely expired, and was issued a higher fencing token, 6.\n\nBecause tokens only increase, the protected resource can use the token to tell a late, stale write apart from a valid, current one."}, "lock": {"d": "The lease itself — a lock with a time-to-live, so a crashed or paused holder can't block everyone else forever.\n\nBeing purely time-based is also its risk: it expires whether or not the old holder actually stopped working, which is exactly why a fencing token is needed on top of it.", "links": [{"label": "Same shape for background jobs: leases, heartbeats, visibility timeouts", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/leases"}]}, "db": {"d": "The protected resource, which enforces `token >= 6` on writes instead of trusting whichever request arrives first.\n\nThis is what makes the lease safe under a pause: even if the old holder's write arrives after the new holder's, its token, 5, is too low and can be rejected."}}, "edges": {"newh>lock": {"d": "The new holder observes that the old lease's TTL has passed and treats the lock as free."}, "oldh>db": {"d": "The paused old holder, unaware time has passed, finally writes — using its stale token, 5."}, "newh>db": {"d": "The new holder writes with its higher token, 6, so the resource has grounds to reject the old holder's write if it lands out of order."}}, "walk": ["oldh", "newh", "newh>lock", "lock", "oldh>db", "newh>db", "db"]},
  "sd:early-exit": {"nodes": {"req": {"d": "The request arrives before any decision has been made about whether it even needs a model."}, "rules": {"d": "The rule check is a deterministic layer — exact matches, regexes, a cache lookup — tried before any model call. It answers what it can recognize outright, in constant time, for effectively no cost."}, "out": {"d": "The answer is returned to the caller, whether it came from a rule match or from the model."}, "model": {"d": "The model only runs when the rule check has nothing to offer — it is the expensive fallback, not the default path."}}, "edges": {"req>rules": {"d": "Every request is checked against the deterministic rules first, before any model is invoked."}, "rules>out": {"d": "A rule match returns an answer immediately, without ever calling the model."}, "rules>model": {"d": "Only requests the rules don't recognize are passed on to the model."}, "model>out": {"d": "The model's answer becomes the final answer for requests that reached it."}}, "walk": ["req", "req>rules", "rules", "rules>out", "rules>model", "model", "model>out", "out"]},
  "sd:effect-classes": {"nodes": {"call": {"d": "A tool call is a proposed action before it's been sorted by what it actually does to the world."}, "classify": {"d": "Classify effect tags the call into one of three buckets based on what happens if it runs: does it only read, can it be undone, or is it permanent. This tagging is what every downstream safety decision — confirm, sandbox scope, audit — is actually built on.", "links": [{"label": "Kitaru docs: tool policies as effect classes", "url": "https://docs.zenml.io/kitaru/guides/replay-and-overrides"}]}, "readEx": {"d": "Read actions — a search, a file view, a lookup — have no side effects, so they run freely without any gate."}, "reversibleEx": {"d": "Reversible actions can be undone after the fact, so they get an undo window instead of an upfront block: the action runs, and there's a period during which it can still be rolled back."}, "irreversibleEx": {"d": "Irreversible actions cannot be undone once they happen — sending an email, deleting a record, a payment — so they need explicit confirmation before they run at all, not after.", "links": [{"label": "Technique: human confirmation and undo windows", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/hitl-undo"}]}}, "edges": {"call>classify": {"d": "Every tool call is tagged with an effect class before any decision is made about how to handle it."}, "classify>readEx": {"d": "Calls classified as read-only run without any additional gate."}, "classify>reversibleEx": {"d": "Calls classified as reversible run immediately but open an undo window."}, "classify>irreversibleEx": {"d": "Calls classified as irreversible are routed to a human for confirmation before they're allowed to run at all."}}, "walk": ["call", "call>classify", "classify", "classify>readEx", "readEx", "classify>reversibleEx", "reversibleEx", "classify>irreversibleEx", "irreversibleEx"]},
  "sd:email-agent:email-and-calendar-agent-high-level-desi": {"nodes": {"user": {"d": "The person the agent works for, reachable over SMS or a chat app. Every action the agent takes on their behalf, other than a few pre-approved silent ones, is confirmed with them first."}, "conv": {"d": "The channel boundary: receives inbound messages over a webhook, streams responses back over SSE, and carries confirmation replies for actions awaiting approval. It is the only piece that knows which transport the user is on."}, "mem": {"d": "Durable facts about the user that outlive any single conversation: contacts, preferences, and things they've told the agent before. The orchestrator reads this before planning, so it doesn't ask the user something it was already told.", "links": [{"label": "AI Engineering from Scratch: memory, virtual context, MemGPT", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/14-agent-engineering/07-memory-virtual-context-memgpt"}]}, "model": {"d": "Routes each model call to a cheaper small model or a larger one depending on the task, rather than sending everything to the most expensive model available.", "links": [{"label": "Pattern: model routing and tiering", "url": "SYSTEM%20DESIGN.html#/patterns/llm-cost/routing"}]}, "orch": {"d": "Runs the agent's turn: reads memory, asks the model to plan, and executes tool calls in a bounded loop, so a confused plan can't run forever. Every proposed action it produces goes through the verdict gate before anything happens in the world.", "links": [{"label": "Pattern: budget caps and loop detection", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/budgets"}]}, "tools": {"d": "Executes the orchestrator's typed tool calls: reading mail or calendar data, or, once confirmed, making a change. Typed means each tool has a fixed schema, so the model can't invent a call the executor doesn't know how to run."}, "providers": {"d": "The real external mail and calendar services the agent actually reads and writes. Every read or write on the user's data ultimately lands here."}, "sync": {"d": "Keep the local cache current: receive provider push notifications and pull deltas so the agent isn't calling Gmail or Calendar directly on every question. A sync also kicks off a triage run so the agent can act on new mail without being asked."}, "cache": {"d": "A local, searchable copy of the user's mail and calendar, kept current by the sync workers. The tool executor reads from here for anything that doesn't need a live write, which is most reads."}, "gate": {"d": "A deterministic check between what the model wants to do and what actually happens: scores every proposed action by risk and decides whether it can proceed silently, needs the user's confirmation, or should be blocked.", "links": [{"label": "Pattern: deterministic policy gate", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/policy-gate"}]}, "notify": {"d": "Sends the user whatever they need to see: a confirmation request before a risky action, a clarifying question, or a report of what already happened."}, "trace": {"d": "Records every turn so it can be replayed later against test scenarios, the mechanism that lets a change to the agent be checked against real past behavior before it ships.", "links": [{"label": "Pattern: transcript checkpoint every turn", "url": "SYSTEM%20DESIGN.html#/patterns/agent-durability/transcript-checkpoint"}]}, "outbox": {"d": "Holds an approved action until it is executed exactly once against the real provider, with a window to undo it afterward. This is what prevents a retried request from sending the same email twice.", "links": [{"label": "Pattern: transactional outbox", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/outbox"}]}}, "edges": {"user>conv": {"d": "The user's message arrives over whichever channel they used."}, "conv>orch": {"d": "The conversation API hands the request to the agent orchestrator."}, "orch>mem": {"d": "The orchestrator pulls known facts and preferences before planning."}, "orch>model": {"d": "The orchestrator asks the model to plan the next step or steps."}, "orch>tools": {"d": "The orchestrator calls tools to read the data it needs to plan or answer."}, "tools>providers": {"d": "A tool call that needs live data goes straight to the provider API."}, "tools>cache": {"d": "A tool call that can be satisfied from the synced local copy reads the cache instead."}, "providers>sync": {"d": "A provider push notification tells the sync worker something changed."}, "sync>cache": {"d": "The sync worker writes the new or changed item into the local cache."}, "sync>orch": {"d": "New mail triggers a triage run, so the agent can propose actions on it without the user asking."}, "orch>gate": {"d": "Every action the orchestrator wants to take is sent to the verdict gate before it happens."}, "gate>notify": {"d": "An action needing approval, or a question needing an answer, is sent to the user through the notifier."}, "gate>trace": {"d": "Every gate verdict is recorded for later replay."}, "gate>outbox": {"d": "An action cleared to proceed, silently or after confirmation, is placed in the outbox for execution."}, "notify>user": {"d": "The notifier's message reaches the user."}, "outbox>providers": {"d": "The outbox executes the approved action against the real provider exactly once."}}, "walk": ["user", "user>conv", "conv", "conv>orch", "orch", "orch>mem", "mem", "orch>model", "model", "orch>tools", "tools", "tools>providers", "providers", "tools>cache", "cache", "providers>sync", "sync", "sync>cache", "sync>orch", "orch>gate", "gate", "gate>notify", "notify", "notify>user", "gate>trace", "trace", "gate>outbox", "outbox", "outbox>providers"]},
  "sd:env-snapshots": {"nodes": {"env": {"d": "The environment is the sandbox filesystem where an agent's real work-in-progress lives — files it created, state it modified — as opposed to the transcript of what it decided to do."}, "snap": {"d": "A snapshot captures the environment's actual state at a point in time, taken every N turns rather than continuously, trading some recovery precision for not paying the cost of snapshotting on every single step.", "links": [{"label": "Postgres docs: template databases", "url": "https://www.postgresql.org/docs/current/manage-ag-templatedbs.html"}]}, "newenv": {"d": "The new sandbox is restored from the most recent snapshot after a failure, giving a replacement worker real files and state to resume with, not just a log of past intentions."}}, "edges": {"env>snap": {"d": "The environment's filesystem state is captured into a snapshot on a fixed cadence, every N turns."}, "snap>newenv": {"d": "After a failure, the most recent snapshot is used to restore a new sandbox to a close approximation of where the old one left off."}}, "walk": ["env", "env>snap", "snap", "snap>newenv", "newenv"]},
  "sd:eval-gate": {"nodes": {"change": {"d": "A proposed change is anything that could affect output quality — a new prompt, a different model, a retrieval tweak — before it's known whether it's actually an improvement."}, "golden": {"d": "The golden set is a fixed collection of test cases with known-good expected answers, used as a stable yardstick so every change is measured against the same bar."}, "gate": {"d": "The eval gate runs the proposed change against the golden set and compares the resulting score to a threshold. It is a deterministic decision point: the score either clears the bar or it doesn't.", "links": [{"label": "Anthropic: demystifying evals for AI agents", "url": "https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents"}, {"label": "Hamel Husain: your AI product needs evals", "url": "https://hamel.dev/blog/posts/evals/"}]}, "release": {"d": "Ships means the change passed the gate and is released to production."}, "blocked": {"d": "Blocked means the change failed to clear the threshold and stays out of production until it's fixed."}}, "edges": {"change>gate": {"d": "The proposed change runs against the eval suite before it can ship."}, "golden>gate": {"d": "The gate compares the change's score against the fixed golden set, not against a moving target."}, "gate>release": {"d": "A change that clears the threshold is released."}, "gate>blocked": {"d": "A change that doesn't clear the threshold is blocked from release."}}, "walk": ["change", "golden", "change>gate", "golden>gate", "gate", "gate>release", "release", "gate>blocked", "blocked"]},
  "sd:event-sourcing": {"nodes": {"cmd": {"d": "Command is an intent to change something: not the change itself, but what triggers one being recorded."}, "log": {"d": "Event log is append-only and immutable: nothing is ever updated or deleted, only added to. It is the actual source of truth here, not a derived copy of some other store."}, "projector": {"d": "Projector reads the event log and replays it to compute what the current state should be; state is a derived view, not stored directly."}, "state": {"d": "Current state is rebuilt from the log rather than being the thing that's directly written to; if it's ever wrong, or needs a new shape, it can be recomputed from the same events.", "links": [{"label": "Design: alfred_'s turn_effects and side_effects tables are this ledger; behavioral assertions read it, not the assistant's text", "url": "SYSTEM%20DESIGN.html#/designs/alfred/patterns"}, {"label": "Design: prior-auth's append-only audit log records every state change and every human access", "url": "SYSTEM%20DESIGN.html#/designs/prior-auth/patterns"}]}}, "edges": {"cmd>log": {"d": "A command results in an event being appended to the log; this append is the actual write, and it's the only kind of write this system does."}, "log>projector": {"d": "The projector reads through the log's events in order to reconstruct state."}, "projector>state": {"d": "The projector derives the current state from everything it has replayed so far."}}, "walk": ["cmd", "cmd>log", "log", "log>projector", "projector", "projector>state", "state"]},
  "sd:exactly-once": {"nodes": {"producer": {"d": "Producer sends a message meant to trigger some effect exactly once, even though the transport underneath cannot make that promise on its own."}, "queue": {"d": "Queue is only at-least-once: it can and will redeliver a message the consumer already processed, typically after a crash or a slow acknowledgment."}, "consumer": {"d": "Consumer treats every delivery as potentially a duplicate: it checks an id before doing anything, rather than trusting a message arrives only once.", "links": [{"label": "Design: email-agent stamps an action id in a header and searches sent mail for it before any retry", "url": "SYSTEM%20DESIGN.html#/designs/email-agent/patterns"}]}, "dedupe": {"d": "Dedupe table stores which idempotency keys have already been acted on, so a second delivery of the same message can be recognized and skipped.", "links": [{"label": "Design: alfred_'s v6_webhook_events dedupes envelopes, and write tools replay prior results by idempotency key", "url": "SYSTEM%20DESIGN.html#/designs/alfred/patterns"}]}}, "edges": {"producer>queue": {"d": "The producer sends a message once, but the underlying queue offers no guarantee it will be delivered only once."}, "queue>consumer": {"d": "Delivery can happen more than once; this edge is explicitly asynchronous and explicitly 'maybe twice', not a guarantee of exactly one."}, "consumer>dedupe": {"d": "Before acting, the consumer checks whether this message's id has been seen: if so it skips the action, if not it does the action and records the id."}}, "walk": ["producer", "producer>queue", "queue", "queue>consumer", "consumer", "consumer>dedupe", "dedupe"]},
  "sd:fanout-mode": {"nodes": {"postsmall": {"d": "An account with a small, fixed audience — 50 followers in this example.\n\nBecause the fan-out cost (writing the post into 50 inboxes) is cheap and bounded, it happens immediately, at post time."}, "postbig": {"d": "An account with a huge audience — 50 million followers — which makes eager fan-out prohibitively expensive at post time.\n\nPushing one post into 50 million inboxes synchronously would create a massive write spike: the classic hot-key problem in write scaling.", "links": [{"label": "Problem this avoids: a hot partition from one overloaded key", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-writes/hot-partition"}]}, "inbox": {"d": "A per-follower list of posts to show, pre-computed and written at post time.\n\nThis is denormalization: the read is cheap (just fetch the list) because the work was already done, once per follower, when the post was created.", "links": [{"label": "Technique: denormalized read models", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-reads/denormalize"}]}, "reader": {"d": "The feed-read path that, for accounts too big to fan out on write, assembles the timeline at read time instead, merging the celebrity's posts in on the fly.\n\nThis trades a cheap write for a more expensive read, paid only when someone actually opens their feed."}}, "edges": {"postsmall>inbox": {"d": "The post is written directly into every follower's inbox as part of handling the post — fan-out on write."}, "postbig>reader": {"d": "Instead of writing into followers' inboxes, the post waits to be merged in whenever a follower's feed is actually read — fan-out on read."}}, "walk": ["postsmall", "postsmall>inbox", "inbox", "postbig", "postbig>reader", "reader"]},
  "sd:flags": {"nodes": {"config": {"d": "Flag config stores a percentage rollout, or an on/off state, that can be changed live without touching code or redeploying anything.", "links": [{"label": "Design: alfred_'s donna_consumer_config holds percentage dials, alfred_feature_flags the kill switches", "url": "SYSTEM%20DESIGN.html#/designs/alfred/patterns"}]}, "svc": {"d": "Service reads the flag config on every request and decides, per request, which code path to take."}, "old": {"d": "Old path is the existing, already-trusted behavior, still serving the majority of traffic here (95%)."}, "new": {"d": "New path is the new behavior being rolled out gradually (5% here), so a bad change only affects a small fraction of traffic before it's caught."}}, "edges": {"config>svc": {"d": "The service reads the current dial live; no deploy is needed to change what percentage sees the new path."}, "svc>old": {"d": "95% of requests are still routed to the proven path."}, "svc>new": {"d": "5% of requests are routed to the new path, the currently rolling-out fraction."}}, "walk": ["config", "config>svc", "svc", "svc>old", "old", "svc>new", "new"]},
  "sd:geo:cells-first-then-exact-distance": {"nodes": {"client": {"d": "Client is the caller issuing a 'near me' query with its own coordinates and a search radius."}, "svc": {"d": "Search service turns a location query into two cheap steps: first narrow candidates by grid cell, then check exact distance only on the survivors. It never computes distance against the whole dataset."}, "geo": {"d": "Geo index is a spatial index (geohash, quadtree, or S2/H3 cells) that groups nearby points so a query only has to look at a handful of cells instead of scanning everything. Which scheme it uses trades off simplicity, even coverage, and how well it copes with moving points.", "links": [{"label": "Technique: geohash", "url": "SYSTEM%20DESIGN.html#/patterns/geo/geohash"}, {"label": "Technique: quadtree", "url": "SYSTEM%20DESIGN.html#/patterns/geo/quadtree"}, {"label": "Technique: S2/H3 cells", "url": "SYSTEM%20DESIGN.html#/patterns/geo/cells"}]}, "db": {"d": "Places DB holds full records for every place or entity; the geo index only stores enough to identify candidates, so a match still needs a lookup here to get the real data."}, "updates": {"d": "Location updates come from moving entities (drivers, say) and constantly rewrite their position in the geo index, independent of any search happening at the same time."}}, "edges": {"client>svc": {"d": "The raw query, location and radius, reaches the service first."}, "svc>geo": {"d": "The service asks the index for the query's cell and its immediate neighbors, to catch points just across a cell boundary."}, "svc>db": {"d": "Candidate ids that survive the distance filter get hydrated into full records here."}, "updates>geo": {"d": "A moving entity's new position is upserted into the index continuously, independent of any query in flight."}}, "walk": ["client", "client>svc", "svc", "svc>geo", "geo", "updates", "updates>geo", "svc>db", "db"]},
  "sd:geohash": {"nodes": {"point": {"d": "Point is a raw latitude/longitude coordinate, the input to the whole scheme."}, "encode": {"d": "Encode turns the coordinate into a geohash string, where each added character narrows the represented area to a smaller cell."}, "cell": {"d": "Cell 9q8yy is one such geohash string, shared by every point whose coordinates round to the same prefix — that shared prefix is what turns a proximity query into a simple string match."}, "neighbors": {"d": "8 neighbors are the cells surrounding the query's cell. They have to be checked separately because two points can be physically close but fall on opposite sides of a cell boundary, sharing no prefix at all."}}, "edges": {"point>encode": {"d": "The raw coordinate is fed into the geohash encoding function."}, "encode>cell": {"d": "The resulting string is matched to the shared-prefix cell it belongs to."}, "cell>neighbors": {"d": "Because a point can sit near a cell's edge, the query also checks the eight adjacent cells so it doesn't miss a close match on the other side of a boundary."}}, "walk": ["point", "point>encode", "encode", "encode>cell", "cell", "cell>neighbors", "neighbors"]},
  "sd:grounding:generate-verify-measure": {"nodes": {"q": {"d": "The question is what a user actually asked, the thing the rest of the pipeline exists to answer accurately."}, "src": {"d": "Sources are the underlying documents, chunked and stored with enough location information (page, section, span) that a later claim can be checked against exactly the passage it came from."}, "ret": {"d": "Retrieve searches the sources for passages relevant to the question, typically combining keyword and vector search and reranking the results, and hands the top passages to generation.", "links": [{"label": "Technique: retrieval-augmented generation", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/rag"}]}, "gen": {"d": "Generate produces a draft answer constrained to a schema, with citation markers tying each claim to a specific retrieved passage. It should be composing from the passages, not writing from memory.", "links": [{"label": "Technique: structured outputs", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/structured"}]}, "verify": {"d": "Verify checks that every citation marker in the draft actually points to a passage that supports the claim next to it. This is what turns 'the model said it cited something' into 'the citation is real.'", "links": [{"label": "Technique: enforced citations and verification", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/citations"}]}, "out": {"d": "Answer or refuse: if verification passes, the cited answer goes out; if it can't be supported, refusing is treated as a valid, correct outcome, not a failure.", "links": [{"label": "Technique: explicit refusal paths", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/refusal"}]}, "evals": {"d": "The eval suite is a fixed golden set of questions with known-good answers, scored regularly and used as a gate: a change to prompts, retrieval, or the model can't ship if it drops the score below a threshold.", "links": [{"label": "Technique: eval suites as release gates", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/eval-gate"}]}}, "edges": {"q>ret": {"d": "The question goes straight to retrieval; nothing is generated before relevant sources are found."}, "ret>src": {"d": "Retrieval searches the source store using hybrid keyword-plus-vector search."}, "ret>gen": {"d": "The retrieved passages, not the raw sources, are what generation actually sees."}, "gen>verify": {"d": "The draft answer, with its citation markers still unchecked, is passed to verification before being shown to anyone."}, "verify>out": {"d": "Only a draft that passes the support check is released as the answer."}, "out>evals": {"d": "Live traces of what got answered, or refused, feed back into the eval suite asynchronously, as evidence of real-world behavior."}, "evals>gen": {"d": "The eval suite's score against the golden set gates whether a proposed change to generation is allowed to ship."}}, "walk": ["q", "q>ret", "ret", "ret>src", "src", "ret>gen", "gen", "gen>verify", "verify", "verify>out", "out", "out>evals", "evals", "evals>gen"]},
  "sd:hashing": {"nodes": {"client": {"d": "Client is whoever is uploading content, which could be a browser or another service acting as one."}, "hash": {"d": "Hasher computes a fingerprint of the uploaded content, deterministically: the same bytes always produce the same hash regardless of filename or upload time."}, "index": {"d": "Hash index is a lookup table that answers one question: has this exact content already been stored? A hit means the upload is a duplicate."}, "storage": {"d": "Object storage is where content is actually kept when it turns out to be new.", "links": [{"label": "Design: coding-agent content-addresses per-repo base snapshots so they're shared across tasks instead of duplicated", "url": "SYSTEM%20DESIGN.html#/designs/coding-agent/patterns"}]}}, "edges": {"client>hash": {"d": "The raw content is streamed to the hasher before anything else happens."}, "hash>index": {"d": "The computed fingerprint is looked up against everything already stored."}, "index>storage": {"d": "3a: if the hash already exists, storage is skipped and the existing object is reused."}}, "walk": ["client", "client>hash", "hash", "hash>index", "index", "index>storage", "storage"]},
  "sd:hitl-undo": {"nodes": {"action": {"d": "The proposed action is what the agent wants to do, before it's known whether it needs a human's sign-off first."}, "confirm": {"d": "Confirm is where an irreversible action stops and waits for a person to approve it explicitly, before anything happens — the only point in this diagram where a human decision gates execution rather than reviews it after the fact."}, "exec": {"d": "Execute is where the action actually happens, either because it was approved by a human or because it was reversible enough not to need approval up front.", "links": [{"label": "Lesson: propose then commit", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/15-autonomous-systems/15-propose-then-commit"}, {"label": "Lesson: checkpoints and rollback", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/15-autonomous-systems/16-checkpoints-rollback"}]}, "undo": {"d": "The undo window is a fixed period — 30 seconds in this diagram — after a reversible action executes, during which it can still be cancelled. Once the window closes, the action is final."}}, "edges": {"action>confirm": {"d": "An action classified as irreversible waits for human confirmation before it can execute."}, "confirm>exec": {"d": "Only after a human approves does an irreversible action proceed to execution."}, "action>exec": {"d": "A reversible action skips confirmation entirely and executes immediately."}, "exec>undo": {"d": "After a reversible action executes, a fixed window opens during which it can still be cancelled."}}, "walk": ["action", "action>confirm", "confirm", "confirm>exec", "action>exec", "exec", "exec>undo", "undo"]},
  "sd:hot-keys": {"nodes": {"client": {"d": "Many different readers, all hammering the exact same key at once."}, "app": {"d": "Decides which of several copies of the hot key to read from, so no single copy takes the full weight of every read."}, "copya": {"d": "One of at least two duplicated copies of a hot key's value, held specifically so a single key under heavy read load doesn't bottleneck on one cache node."}, "copyb": {"d": "The other duplicated copy of the same hot key, chosen at random exactly as often as copy A, so the read load actually splits evenly."}}, "edges": {"client>app": {"d": "Every reader is asking for the exact same key."}, "app>copya": {"d": "The app server picks a copy at random rather than always reading the same one."}, "app>copyb": {"d": "The app server picks a copy at random rather than always reading the same one."}}, "walk": ["client", "client>app", "app", "app>copya", "copya", "app>copyb", "copyb"]},
  "sd:hot-partition": {"nodes": {"writer": {"d": "Writing to what would otherwise be a single, very hot key."}, "p1": {"d": "One of several sub-keys a single hot key was split into (salted), so writes to what used to be one key are now spread across several partitions."}, "p2": {"d": "The other sub-key in this split, taking a share of the writes the original single key used to absorb alone."}, "reader": {"d": "Reads every sub-key and sums them to get back the original value the salting split apart. This is the cost of salting: a write got cheaper, but a read got more expensive."}}, "edges": {"writer>p1": {"d": "A write is salted, a suffix or hash added, and lands on one of the sub-keys."}, "writer>p2": {"d": "Another write, salted differently, lands on the other sub-key."}, "p1>reader": {"d": "The reader reads this sub-key as part of reconstructing the total."}, "p2>reader": {"d": "The reader reads this sub-key too, and adds it to the running total."}}, "walk": ["writer", "writer>p1", "p1", "p1>reader", "writer>p2", "p2", "p2>reader", "reader"]},
  "sd:hybrid-rerank": {"nodes": {"query": {"d": "Query is the user's search text, sent to both retrieval methods at once rather than picking one."}, "keyword": {"d": "Keyword (BM25) returns candidates matched on exact terms: fast, precise on exact matches, blind to meaning."}, "vector": {"d": "Vector (ANN) returns candidates matched on semantic similarity, catching paraphrases and related concepts that share no exact words with the query."}, "fuse": {"d": "Fuse (RRF) merges the two ranked candidate lists into one, using reciprocal rank fusion, down to roughly 40 candidates; a cheap combination step, not a re-scoring.", "links": [{"label": "Design: notebooklm reranks vector-plus-BM25 candidates from ~40 down to ~12, filtered by notebook_id", "url": "SYSTEM%20DESIGN.html#/designs/notebooklm/patterns"}]}, "rerank": {"d": "Reranker is a cross-encoder, a more expensive model that scores the query against each of the ~40 fused candidates directly and cuts the list down to the actual top ~10 returned to the user.", "links": [{"label": "Session: Design: evidence ingestion from messy documents", "url": "index.html#/s/2/4"}]}}, "edges": {"query>keyword": {"d": "The same query is sent to the keyword search in parallel with the vector search."}, "query>vector": {"d": "The same query is also sent to the vector search; both run at once, not one after the other."}, "keyword>fuse": {"d": "Keyword results are merged into the fusion step."}, "vector>fuse": {"d": "Vector results are merged into the same fusion step."}, "fuse>rerank": {"d": "The ~40 fused candidates are reranked by the cross-encoder down to the final ~10."}}, "walk": ["query", "query>keyword", "keyword", "query>vector", "vector", "keyword>fuse", "vector>fuse", "fuse", "fuse>rerank", "rerank"]},
  "sd:idempotency": {"nodes": {"client": {"d": "The caller, which attaches an idempotency key to its request — the same key on every retry of what it considers the same logical operation.\n\nThe key has to be chosen by the client, not generated by the server, because its purpose is to survive across retries of a request the client is repeating on purpose.", "links": [{"label": "Reading: designing APIs with idempotency (Stripe)", "url": "https://stripe.com/blog/idempotency"}]}, "check": {"d": "A lookup against a store of keys already seen, done before the actual side effect runs.\n\nThis is usually implemented as an atomic insert, `INSERT ... ON CONFLICT DO NOTHING`, so that even two retries arriving at the same moment can't both slip through as 'new'.", "links": [{"label": "How the check is usually implemented: atomic conditional update", "url": "SYSTEM%20DESIGN.html#/patterns/contention/atomic"}, {"label": "Reading: idempotency keys in Postgres (Brandur Leach)", "url": "https://brandur.org/idempotency-keys"}]}, "effect": {"d": "The actual side effect — charge the card, send the email — that must run exactly once no matter how many times the request is retried.\n\nIt only runs the first time a given key is seen; every later retry skips straight to returning the stored result."}, "stored": {"d": "The result of the side effect, saved under the idempotency key so a retry can return it without re-running anything.\n\nThis is what makes the operation safe under at-least-once delivery: retries become reads of a stored result instead of re-executions.", "links": [{"label": "The guarantee this delivers: exactly-once effects from at-least-once delivery", "url": "SYSTEM%20DESIGN.html#/patterns/consistency/exactly-once"}]}}, "edges": {"client>check": {"d": "The client's request arrives carrying its idempotency key, checked before anything else happens."}, "check>effect": {"d": "If the key hasn't been seen before, the side effect is allowed to run for the first time."}, "effect>stored": {"d": "The side effect's result is saved, keyed by the idempotency key, once it completes."}, "check>stored": {"d": "If the key has already been seen, the request skips the side effect entirely and gets back the previously stored result."}}, "walk": ["client", "client>check", "check", "check>effect", "effect", "effect>stored", "stored", "check>stored"]},
  "sd:indexing": {"nodes": {"app": {"d": "The service issuing a query it expects to be fast: look up a user's records by user_id and a time range, not scan the whole table."}, "index": {"d": "A structure (typically a B-tree) built on the columns the query filters by, here user_id and created_at, so the database can jump straight to matching rows instead of reading every row."}, "rows": {"d": "The small set of rows the index actually points at. The whole point of an index is that this is a handful of rows, not a full-table scan."}}, "edges": {"app>index": {"d": "The app server's query goes through the index first, not the table directly."}, "index>rows": {"d": "The index seeks straight to the matching rows."}}, "walk": ["app", "app>index", "index", "index>rows", "rows"]},
  "sd:injection": {"nodes": {"untrusted": {"d": "Untrusted text is any content the system didn't generate and can't vouch for — an email body, a scraped web page, an uploaded document. It might contain instructions aimed at the agent itself, indistinguishable at a glance from ordinary content."}, "reader": {"d": "Quarantine is a model instance whose only job is to read untrusted text and extract specific fields — a date, a name, an amount — never to pass along free text or act on anything it reads. This is the boundary that stops an instruction hidden in the text ('ignore previous instructions and...') from ever reaching the part of the system that plans actions.", "links": [{"label": "Lesson: prompt-injection defense", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/14-agent-engineering/27-prompt-injection-defense"}, {"label": "Lesson: indirect prompt injection", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/18-ethics-safety-alignment/15-indirect-prompt-injection"}]}, "planner": {"d": "The planner receives only the extracted fields, but treats them as tainted — data that originated from something untrusted, even after being reduced to a plain field. That taint travels with the data."}, "confirm": {"d": "Confirm is where taint escalates a decision: an action whose arguments trace back to untrusted text requires human confirmation, even if the same action with clean input wouldn't."}}, "edges": {"untrusted>reader": {"d": "Untrusted text is routed to the quarantined reader rather than to the planner directly."}, "reader>planner": {"d": "Only extracted fields cross this boundary, never raw untrusted text, but those fields still carry a taint marker."}, "planner>confirm": {"d": "When a proposed action's arguments trace back to tainted input, the planner is forced to route it through human confirmation instead of acting on it directly."}}, "walk": ["untrusted", "untrusted>reader", "reader", "reader>planner", "planner", "planner>confirm", "confirm"]},
  "sd:invalidation": {"nodes": {"db": {"d": "Wherever a row change actually happens; the write itself is unremarkable, it's what happens after that matters here."}, "stream": {"d": "Captures every row change as an event, in order, without the writer needing to know anyone is listening.", "links": [{"label": "Pattern: change data capture (CDC)", "url": "SYSTEM%20DESIGN.html#/patterns/consistency/cdc"}]}, "consumer": {"d": "Reads the change stream and decides what, if anything, needs to happen as a result of this particular change."}, "cache": {"d": "Has the stale key removed once the consumer reports the underlying data changed, rather than waiting for a TTL to expire on its own."}}, "edges": {"db>stream": {"d": "A row change is captured onto the change stream."}, "stream>consumer": {"d": "The CDC consumer reads the change event."}, "consumer>cache": {"d": "The consumer evicts the now-stale key from the cache."}}, "walk": ["db", "db>stream", "stream", "stream>consumer", "consumer", "consumer>cache", "cache"]},
  "sd:inverted": {"nodes": {"doc": {"d": "Documents are the raw text being indexed, arriving before any tokenization happens."}, "tokenizer": {"d": "Tokenizer splits raw text into terms, the unit the index is actually built on, not whole documents."}, "index": {"d": "Inverted index maps each term to the list of document ids containing it. It's called 'inverted' because a normal index goes document-to-terms; this one goes term-to-documents, which is what makes keyword lookup fast."}, "query": {"d": "Query here is a set of search terms and any filters, arriving separately from indexing."}, "rank": {"d": "BM25 rank scores and orders the matched documents by relevance and applies filters; this is where 'best match' gets decided, not just 'which documents match'.", "links": [{"label": "Design: ticketmaster uses Elasticsearch to serve event search", "url": "SYSTEM%20DESIGN.html#/designs/ticketmaster/patterns"}]}}, "edges": {"doc>tokenizer": {"d": "Documents are broken into terms before indexing."}, "tokenizer>index": {"d": "Each term is recorded against the ids of every document containing it."}, "query>index": {"d": "A search looks up the index by term, not by scanning documents."}, "index>rank": {"d": "Matching documents are ranked with BM25 and any filters are applied before results are returned."}}, "walk": ["doc", "doc>tokenizer", "tokenizer", "tokenizer>index", "index", "query", "query>index", "index>rank", "rank"]},
  "sd:kitaru:kitaru-high-level-design": {"nodes": {"dev": {"d": "The engineer using Kitaru, through whichever interface fits the moment: a CLI, an MCP client, or the web UI. Every one of them is just a client to the same server."}, "src": {"d": "Where a real agent session comes from before it's a Kitaru replay: an existing tracing tool a team already logs to."}, "api": {"d": "The server that owns every session, cohort, and task, deliberately written to never run the customer's own agent code itself; that's the worker's job.", "links": [{"label": "Session: Kitaru at mechanism depth", "url": "index.html#/w/4"}]}, "tasks": {"d": "Holds work for a worker to claim, with a lease and a heartbeat, so a worker that dies mid-replay doesn't leave the task stuck forever.", "links": [{"label": "Pattern: leases, heartbeats, visibility timeouts", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/leases"}]}, "pg": {"d": "The relational record of every replay session, its individual steps (nodes), and the cohorts they're grouped into for comparison."}, "blob": {"d": "Holds the large parts of a session, full tool outputs and model responses, that don't belong inline in a database row.", "links": [{"label": "Pattern: metadata in the database, bytes in object storage", "url": "SYSTEM%20DESIGN.html#/patterns/large-blobs/metadata-split"}]}, "worker": {"d": "Claims a task and spins up the customer's own environment, their exact dependency versions, to run their agent under conditions that match production."}, "plug": {"d": "Pluggable code, an importer that understands a specific trace format, or an evaluator that scores a replay, each run in its own isolated environment so one customer's dependencies can't collide with another's.", "links": [{"label": "Pattern: least privilege and sandboxing", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/least-privilege"}]}, "agent": {"d": "The customer's actual agent code, running as a subprocess with adapter hooks that intercept its tool calls so they can be answered from the recording.", "links": [{"label": "What running a subprocess without a sandbox gives away", "url": "https://www.pandastack.ai/blog/how-to-sandbox-untrusted-code/"}]}, "model": {"d": "The one thing in a replay that is never faked: the model itself always runs live, because replaying a stale model response would test yesterday's model, not today's agent."}, "live": {"d": "When a tool call has no matching recorded response, and the operator has explicitly allowed it, the call passes straight through to the real tool instead of failing the replay.", "links": [{"label": "Kitaru docs: replay and overrides, the cache key and on_miss", "url": "https://docs.zenml.io/kitaru/guides/replay-and-overrides"}]}}, "edges": {"dev>api": {"d": "The developer's CLI, MCP client, or UI all talk to the same Kitaru server."}, "api>pg": {"d": "The server persists sessions, nodes, and cohorts to Postgres."}, "api>blob": {"d": "The server stores large payloads in blob storage."}, "api>tasks": {"d": "The server enqueues a task for a worker to pick up."}, "worker>tasks": {"d": "A worker claims the next available task."}, "worker>plug": {"d": "The worker spawns the relevant importer or evaluator in its own isolated environment."}, "src>plug": {"d": "An external trace source exports its data for an importer to consume."}, "worker>agent": {"d": "The worker spawns the customer's agent as a subprocess, tagged with the replay it's running."}, "agent>api": {"d": "The agent's tool calls are intercepted and looked up against the recorded session through the server."}, "agent>model": {"d": "The agent's model calls still go to the real model provider."}, "agent>live": {"d": "A tool call with no matching recording, if allowed, passes through to the live tool."}}, "walk": ["dev", "dev>api", "api", "api>pg", "pg", "api>blob", "blob", "api>tasks", "tasks", "worker", "worker>tasks", "worker>plug", "plug", "src", "src>plug", "worker>agent", "agent", "agent>api", "agent>model", "model", "agent>live", "live"]},
  "sd:large-blobs:bytes-bypass-the-api": {"nodes": {"client": {"d": "The browser or app uploading or downloading a large file.\n\nIt never sends the actual file bytes through the application's own API — that's the point the title is making."}, "s3": {"d": "Object storage that receives the file bytes directly from the client, split into parts, with support for resuming an interrupted upload.\n\nSending bytes here instead of through the application's servers keeps large transfers off the API tier entirely.", "links": [{"label": "Technique: multipart and resumable uploads", "url": "SYSTEM%20DESIGN.html#/patterns/large-blobs/multipart"}]}, "api": {"d": "The application's file API, which authorizes the upload and hands the client a short-lived signed URL — it never touches the file's bytes itself.\n\nIts job is authorization and bookkeeping, not moving bytes.", "links": [{"label": "Technique: presigned URLs", "url": "SYSTEM%20DESIGN.html#/patterns/large-blobs/presigned"}, {"label": "Same principle: scoped, short-lived access", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/least-privilege"}]}, "cdn": {"d": "A content delivery network serving downloads through signed, expiring links rather than the object storage's own address.\n\nThis puts a cache close to the reader and keeps the underlying storage bucket from being addressed, or hit, directly.", "links": [{"label": "Technique: CDN with signed URLs", "url": "SYSTEM%20DESIGN.html#/patterns/large-blobs/cdn-signed"}]}, "events": {"d": "A notification the object storage emits the moment a new object finishes uploading.\n\nThis is what triggers processing without the API needing to poll storage for new files.", "links": [{"label": "Technique: storage events", "url": "SYSTEM%20DESIGN.html#/patterns/large-blobs/storage-events"}]}, "meta": {"d": "A database row tracking the file's state, starting as pending the moment the upload begins, before any bytes have necessarily arrived.\n\nKeeping this separate from the object storage itself is what lets the application query which files exist and what state they're in without ever touching the bytes.", "links": [{"label": "Technique: metadata in the database, bytes in object storage", "url": "SYSTEM%20DESIGN.html#/patterns/large-blobs/metadata-split"}]}, "proc": {"d": "A worker that reacts to the storage event by hashing, virus-scanning, or thumbnailing the newly uploaded object.\n\nOnly after it finishes does the file's metadata row flip from pending to ready — before that, the upload exists but isn't considered usable yet.", "links": [{"label": "Technique: hashing (content-addressing, integrity)", "url": "SYSTEM%20DESIGN.html#/patterns/large-blobs/hashing"}]}}, "edges": {"client>api": {"d": "The client asks the file API to authorize an upload and gets back a presigned URL."}, "client>s3": {"d": "The client uploads the actual bytes, in parts, directly to object storage — not through the application's API."}, "client>cdn": {"d": "Downloads go through the CDN's signed URL, not directly to object storage or through the API."}, "api>meta": {"d": "The file API creates a metadata row before the bytes necessarily exist, so the file's existence is tracked from the moment upload starts."}, "s3>events": {"d": "Object storage fires a notification the moment the upload completes."}, "events>proc": {"d": "A processing worker consumes that notification to kick off post-upload work."}, "proc>meta": {"d": "Once processing finishes, the processor flips the metadata row from pending to ready."}}, "walk": ["client", "client>api", "api", "api>meta", "meta", "client>s3", "s3", "s3>events", "events", "events>proc", "proc", "proc>meta", "client>cdn", "cdn"]},
  "sd:leases": {"nodes": {"job": {"d": "The unit of work being leased out to whichever worker is available.\n\nA lease is a time-boxed claim, not a permanent assignment — it has to be renewed, or it lapses."}, "w1": {"d": "Worker A, which took the lease but then stopped sending heartbeats — crashed, network-partitioned, or just slow.\n\nThe system can't tell the difference between dead and merely slow from a missed heartbeat alone; it can only act on the absence of a signal.", "links": [{"label": "The pool this worker belongs to: queue plus worker pool", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/worker-pool"}]}, "lease": {"d": "A timer tracking how long it's been since the last heartbeat from whoever holds the job, tied to a visibility timeout.\n\nOnce this timer runs out without a heartbeat, the job is treated as abandoned, whether or not the original worker is actually still working on it.", "links": [{"label": "Same underlying mechanism: distributed locks and leases with TTL", "url": "SYSTEM%20DESIGN.html#/patterns/contention/distributed-lock"}]}, "w2": {"d": "Worker B, which becomes eligible to claim the job only after the lease has expired.\n\nIt has no way of knowing whether worker A is truly dead or will show up later with a stale result — this is why the job's side effect usually needs to be idempotent."}}, "edges": {"job>w1": {"d": "Worker A takes out the initial lease on the job."}, "w1>lease": {"d": "Worker A stops heartbeating, which the lease timer notices as an absence of a signal rather than a definite failure."}, "lease>job": {"d": "Once the lease's timeout passes with no heartbeat, the job is marked available again."}, "job>w2": {"d": "Worker B takes out a fresh lease on the same job and starts working on it."}}, "walk": ["job", "job>w1", "w1", "w1>lease", "lease", "lease>job", "job>w2", "w2"]},
  "sd:least-privilege": {"nodes": {"agent": {"d": "The agent requests an action, but never runs with more access than the sandbox around it grants — it can only ask, it can't act directly on anything outside that scope."}, "sandbox": {"d": "The sandbox holds a scoped token: credentials limited to exactly the actions this agent should ever need, nothing broader. This is what makes 'least privilege' concrete rather than aspirational — the token itself cannot perform actions outside its scope, regardless of what the agent asks for.", "links": [{"label": "What running without a sandbox gives away", "url": "https://www.pandastack.ai/blog/how-to-sandbox-untrusted-code/"}, {"label": "Lesson: Claude Code permission modes", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/15-autonomous-systems/10-claude-code-permission-modes"}]}, "allowed": {"d": "Opening a pull request is in scope for this agent's token; the sandbox permits it because it's within the boundary the token was issued for."}, "blocked": {"d": "Merging is denied by policy: the sandbox's token has no permission to merge, so even if the agent proposed it, there's nothing to approve. The action simply isn't possible with the credentials it has."}}, "edges": {"agent>sandbox": {"d": "Every action the agent wants to take runs through the sandbox, never with the agent's own unscoped access."}, "sandbox>allowed": {"d": "Opening a PR is within the scoped token's permissions, so the sandbox permits it."}, "sandbox>blocked": {"d": "Merging is outside the scoped token's permissions, so the sandbox denies it outright, before any human even needs to weigh in."}}, "walk": ["agent", "agent>sandbox", "sandbox", "sandbox>allowed", "allowed", "sandbox>blocked", "blocked"]},
  "sd:llm-cost:spend-tokens-only-where-they-matter": {"nodes": {"req": {"d": "The request is the unit of work entering the system: one user turn, one API call, one job that will eventually need a model's output. Nothing about its cost has been decided yet — that happens at every guard and gate downstream."}, "exits": {"d": "Early exits are deterministic checks — rule matches, cached lookups, regexes — that can answer a request before any model runs at all.\n\nBecause they run in microseconds and cost nothing per call, they are tried first, catching whatever never needed a language model's judgment. Only what an early exit can't resolve continues on to the response cache and the router.", "links": [{"label": "Technique: deterministic early exits", "url": "SYSTEM%20DESIGN.html#/patterns/llm-cost/early-exit"}]}, "cache": {"d": "The response cache stores full answers keyed by an exact hash or a semantic embedding of the request, so an identical or near-identical question is answered without any generation at all.\n\nA hit returns instantly and skips every downstream cost. In a support or FAQ workload where the same handful of questions repeat constantly, this alone can cut model spend more than any other technique here.", "links": [{"label": "Technique: response and semantic caching", "url": "SYSTEM%20DESIGN.html#/patterns/llm-cost/response-cache"}]}, "router": {"d": "The model router looks at a request that survived the cheap checks and decides which model tier is worth paying for, based on how hard the task actually looks.\n\nEasy classification or extraction goes to a small, cheap model; planning or open-ended writing goes to a large one; anything not time-sensitive can wait for the batch API. The router's whole job is to stop hard-model prices from being paid for easy-model work.", "links": [{"label": "Technique: model routing and tiering", "url": "SYSTEM%20DESIGN.html#/patterns/llm-cost/routing"}]}, "small": {"d": "The small model handles work the router judged easy — classifying intent, extracting a field, matching a category — tasks a lighter, cheaper model answers about as well as a large one, at a fraction of the per-token price."}, "large": {"d": "The large model is reserved for what actually needs it: multi-step planning, long-form writing, reasoning a small model would get wrong. Its prompt reuses a cached prefix (system instructions, tool definitions, retrieved documents) so only the new turn is paid for at full price.", "links": [{"label": "Technique: prompt caching", "url": "SYSTEM%20DESIGN.html#/patterns/llm-cost/prompt-cache"}]}, "batch": {"d": "The batch API queues requests that don't need an answer right now and runs them together, off the interactive path, at a lower per-token rate than synchronous calls.\n\nIt trades latency — results can take minutes to hours — for a substantial cost discount, a good trade for work like nightly summarization or bulk classification that nobody is waiting on.", "links": [{"label": "Technique: batch APIs and parallel calls", "url": "SYSTEM%20DESIGN.html#/patterns/llm-cost/batch-parallel"}]}, "stream": {"d": "The token stream sends output tokens to the client as the model produces them, rather than waiting for the full response.\n\nIt doesn't reduce total token cost, but it cuts perceived latency to first token, often the number that actually matters to a waiting user.", "links": [{"label": "Technique: token streaming", "url": "SYSTEM%20DESIGN.html#/patterns/llm-cost/streaming"}]}}, "edges": {"req>exits": {"d": "Every request is checked against deterministic rules and cached lookups before anything else runs."}, "exits>cache": {"d": "A request the rule check can't resolve is looked up in the response cache next, in case the same question has already been answered."}, "exits>router": {"d": "A cache miss falls through to the router, which decides which model tier is worth the cost."}, "router>small": {"d": "Requests classified as easy go to the small, cheap model."}, "router>large": {"d": "Requests classified as hard go to the large model, which pays for its cached prompt prefix but full price for the new turn."}, "router>batch": {"d": "Requests with no latency requirement go to the batch API instead of running inline."}, "small>stream": {"d": "The small model's output is streamed to the client like any other response."}, "large>stream": {"d": "The large model's output streams token by token so the client sees the first tokens immediately, without waiting for the full generation."}}, "walk": ["req", "req>exits", "exits", "exits>cache", "cache", "exits>router", "router", "router>small", "small", "router>large", "large", "router>batch", "batch", "small>stream", "large>stream", "stream"]},
  "sd:load-shedding": {"nodes": {"writer": {"d": "A mix of requests arriving together, not all equally important."}, "admit": {"d": "Checks each request's priority before letting it through, so that under overload, the system can choose what to sacrifice rather than failing indiscriminately."}, "keep": {"d": "The high-priority class of request, kept and processed even when the system is under load."}, "drop": {"d": "The lower-priority class of request, actively rejected with a 429 when the system is overloaded, so it doesn't compete with the traffic that actually matters."}}, "edges": {"writer>admit": {"d": "Every request passes through admission control first."}, "admit>keep": {"d": "A high-priority request is kept and processed."}, "admit>drop": {"d": "A low-priority request is shed once the system is over its threshold."}}, "walk": ["writer", "writer>admit", "admit", "admit>keep", "keep", "admit>drop", "drop"]},
  "sd:long-running:acknowledge-now-work-later": {"nodes": {"client": {"d": "The caller submitting work that would take too long to hold a request open for — a video render, a large report.\n\nIt submits once, then polls or subscribes for status separately, rather than blocking on one long-lived connection."}, "api": {"d": "The entry point that accepts the request, enqueues the work, and returns immediately instead of waiting for it to finish.\n\nThis is what makes the client's wait bounded and predictable — a fast acknowledgment now, with the actual work tracked separately.", "links": [{"label": "The minimal version of this: async job (202 and a job id)", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/async-job"}]}, "status": {"d": "A record of where the job currently is — queued, running, or done — readable by the client independently of the work itself.\n\nWithout this, there would be no way for the client to know whether its accepted job actually completed, or is still running an hour later."}, "queue": {"d": "The buffer holding submitted jobs, ordered by priority and carrying timeouts, until a worker is free to take one.\n\nA queue here also acts as a shock absorber against load spikes — the API tier stays fast even if workers are temporarily behind.", "links": [{"label": "Technique: priority queues and cancellation", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/priority-cancel"}, {"label": "Session: throughput, latency, queues, backpressure", "url": "index.html#/s/1/1"}]}, "workers": {"d": "The pool of processes that pull jobs off the queue, lease them, and send heartbeats while working so a crash can be detected.\n\nIf a worker stops heartbeating, its lease on the job expires and another worker can pick the job back up.", "links": [{"label": "Technique: leases, heartbeats and visibility timeouts", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/leases"}, {"label": "Technique: queue plus worker pool", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/worker-pool"}]}, "ckpt": {"d": "Saved progress markers a worker writes as it works through a job, so a crash doesn't mean starting over.\n\nA job resumed from a checkpoint continues from the last saved unit of work, not from zero.", "links": [{"label": "Technique: checkpointing", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/checkpointing"}]}, "dlq": {"d": "Where a job goes after failing repeatedly, instead of being retried forever.\n\nThis caps the cost of a job that can never succeed and gives a human a place to look for it later.", "links": [{"label": "Technique: retries with backoff and a dead-letter queue", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/retries-dlq"}]}}, "edges": {"client>api": {"d": "The client submits the long-running request."}, "api>queue": {"d": "The API enqueues the job instead of running it inline."}, "api>status": {"d": "The API creates a status record the client can poll, and returns its id."}, "queue>workers": {"d": "A worker leases the job off the queue when it has capacity."}, "workers>status": {"d": "The worker updates the status record as it makes progress, so polling clients see something other than queued."}, "workers>ckpt": {"d": "The worker periodically saves its progress in case it crashes before finishing."}, "workers>dlq": {"d": "After enough failed attempts, the worker gives up and moves the job to the dead-letter queue instead of retrying indefinitely."}}, "walk": ["client", "client>api", "api", "api>queue", "queue", "api>status", "status", "queue>workers", "workers", "workers>status", "workers>ckpt", "ckpt", "workers>dlq", "dlq"]},
  "sd:metadata-split": {"nodes": {"api": {"d": "The file API handling an upload request.\n\nIt writes to two different systems for one logical upload: a database for queryable metadata, and object storage for the bytes themselves."}, "meta": {"d": "The metadata database, tracking the file's status, starting at pending before the bytes are confirmed written.\n\nAnything you'd want to query — filter by owner, search by name, list all files in a folder — belongs here, not in object storage, which isn't built for that kind of access pattern.", "links": [{"label": "Reading: what object storage is, and why it suits bulk data over a database (AWS)", "url": "https://aws.amazon.com/what-is/object-storage/"}]}, "storage": {"d": "Object storage, holding only the raw bytes, with no query capability of its own.\n\nIt's built for bulk, infrequently-queried data — cheap to store, not efficient to search.", "links": [{"label": "How bytes usually get here: presigned URLs", "url": "SYSTEM%20DESIGN.html#/patterns/large-blobs/presigned"}]}}, "edges": {"api>meta": {"d": "The API writes a metadata row marked pending before the bytes are necessarily confirmed stored."}, "api>storage": {"d": "The API, or more often the client via a presigned URL, writes the actual bytes to object storage."}, "storage>meta": {"d": "Once the bytes are confirmed in storage, the metadata row is updated to ready, asynchronously relative to the original write."}}, "walk": ["api", "api>meta", "meta", "api>storage", "storage", "storage>meta"]},
  "sd:monitoring": {"nodes": {"source": {"d": "Provider inbox is an independent source of truth, counted separately from the pipeline, so it can catch failures the pipeline itself would never notice.", "links": [{"label": "Session: Throughput, latency, queues, backpressure", "url": "index.html#/s/1/1"}]}, "pipeline": {"d": "Pipeline is the system under observation: it processes messages, but a message that never arrives leaves no trace inside the pipeline itself."}, "check": {"d": "Gap check compares two counts, one from the source and one from what the pipeline actually delivered — a completeness check, not an error-rate check."}, "alert": {"d": "Alert fires only when the two counts differ, surfacing failures that would otherwise be silent: no exception was ever thrown, something simply never arrived.", "links": [{"label": "Design: alfred_ samples the provider against staging, since a stage-to-stage diff can't see mail that never entered", "url": "SYSTEM%20DESIGN.html#/designs/alfred/patterns"}]}}, "edges": {"source>pipeline": {"d": "Messages flow from the source into the pipeline for normal processing."}, "source>check": {"d": "The gap check independently samples how many messages the source actually has."}, "pipeline>check": {"d": "The gap check also asks the pipeline how many messages it delivered."}, "check>alert": {"d": "When the two counts don't match, an alert fires — the only path here that catches data that silently never arrived."}}, "walk": ["source", "source>pipeline", "pipeline", "source>check", "pipeline>check", "check", "check>alert", "alert"]},
  "sd:multi-region": {"nodes": {"client": {"d": "Client is normal user traffic, which under healthy conditions only ever talks to one region."}, "regionA": {"d": "Region A is the currently active region, shown down here — the scenario the whole diagram exists to handle."}, "regionB": {"d": "Region B is a second region that takes over when region A fails; whether it's kept warm (active-active) or cold (active-passive) is a real cost and complexity tradeoff not shown here."}, "backup": {"d": "Backups are point-in-time snapshots, independent of region replication, needed because a bad write or a bad migration replicates to region B just as reliably as a good one."}}, "edges": {"client>regionA": {"d": "Under normal conditions, all traffic goes to region A."}, "regionA>regionB": {"d": "Region A continuously replicates its state to region B, asynchronously, so region B is ready to take over."}, "regionA>backup": {"d": "Region A is also snapshotted periodically, independent of replication, so a bad state has a way to be rolled back to a good point in time."}, "client>regionB": {"d": "When region A fails, traffic fails over to region B instead."}}, "walk": ["client", "client>regionA", "regionA", "regionA>regionB", "regionB", "regionA>backup", "backup", "client>regionB"]},
  "sd:multi-step:orchestrated-process-with-compensation": {"nodes": {"api": {"d": "The entry point that kicks off a multi-step process — here, presumably a booking flow.\n\nIts only job is to start the process; the workflow engine takes over everything after this."}, "engine": {"d": "The orchestrator that owns the process end to end: it calls each step in order, tracks which step it's on, and runs timers and retries.\n\nCentralizing control here (orchestration) is the alternative to choreography, where services react to each other's events with no single owner.", "links": [{"label": "Technique: durable workflow engine", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/workflow-engine"}, {"label": "Technique: explicit state machine", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/state-machine"}]}, "history": {"d": "A durable record of what each step did and returned, written as the process progresses.\n\nIf the engine crashes and restarts, it replays this history instead of re-running completed steps from scratch — this is what makes the process resumable rather than starting over."}, "s1": {"d": "Step 1 of the process: reserve.\n\nIt runs first and, if a later step fails, is exactly the step whose effect the compensation has to undo."}, "s2": {"d": "Step 2: charge.\n\nThis is the step that fails in this trace, triggering compensation instead of continuing to step 3."}, "s3": {"d": "Step 3: confirm.\n\nIt never runs in this trace, because step 2 failed first — the engine stops advancing forward and starts compensating instead."}, "comp": {"d": "The compensating logic that runs when a step fails, undoing the effects of whichever earlier steps already completed.\n\nIt is what makes this process safe to abandon partway through: rather than leaving a half-finished booking, it releases what step 1 reserved.", "links": [{"label": "Same idea, choreographed: sagas with compensation", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/saga"}]}}, "edges": {"api>engine": {"d": "Starting the process hands control to the workflow engine, which owns it from here."}, "engine>history": {"d": "As it runs steps, the engine writes to durable history so progress survives a crash."}, "engine>s1": {"d": "Step 1 runs under the engine's direction."}, "engine>s2": {"d": "Step 2 runs next, in order."}, "engine>s3": {"d": "Step 3 would run next, but only if step 2 succeeds."}, "s2>comp": {"d": "Step 2's failure hands control to compensation instead of to step 3."}, "comp>s1": {"d": "Compensation runs the explicit undo for step 1 (releasing the reservation), since step 1's effect can no longer be allowed to stand."}}, "walk": ["api", "api>engine", "engine", "engine>history", "history", "engine>s1", "s1", "engine>s2", "s2", "s2>comp", "comp", "comp>s1", "engine>s3", "s3"]},
  "sd:multipart": {"nodes": {"client": {"d": "The uploader, splitting one large file into multiple parts and uploading them, potentially out of order and in parallel.\n\nSplitting the file this way means a failure only costs the retry of one part, not the whole upload."}, "p1": {"d": "The first part, which uploads successfully on the first attempt.\n\nOnce accepted, it doesn't need to be sent again even if a later part fails."}, "p2": {"d": "The second part, which fails and has to be retried — a dropped connection, a timeout.\n\nBecause parts are independent, retrying this one doesn't require re-uploading part 1."}, "complete": {"d": "The point where object storage checks that every expected part has arrived before assembling them into the final object.\n\nOnly once all parts are present does the upload count as done — a partial set of parts isn't a usable object.", "links": [{"label": "Similar idea: resuming from the last completed unit, not from zero", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/checkpointing"}]}}, "edges": {"client>p1": {"d": "Part 1 uploads and succeeds on the first try."}, "client>p2": {"d": "Part 2 fails at least once and is retried, independently of part 1's success."}, "p1>complete": {"d": "Part 1 counts toward the completion check once it's confirmed received."}, "p2>complete": {"d": "Part 2 also counts, once its retry succeeds — completion needs every part, not just the first to arrive."}}, "walk": ["client", "client>p1", "p1", "client>p2", "p2", "p1>complete", "p2>complete", "complete"]},
  "sd:notebooklm:notebooklm-high-level-design": {"nodes": {"client": {"d": "The browser app the user works in: add sources, ask questions, and request generated artifacts like a study guide or an audio overview.\n\nEverything else in this diagram exists to answer what happens after the user does something here."}, "gw": {"d": "The single entry point for every request from the client: checks the user's identity, enforces rate limits, and routes the call to the right backend service. It fans a request out to three different services (notebook, chat, or artifact) depending on what the user asked for."}, "pg": {"d": "The relational store holding notebook metadata, the list of sources attached to each notebook, and chat history. It is the system of record for everything except the source bytes and generated audio, which live in blob storage instead."}, "nb": {"d": "Owns notebook and source records: creating a notebook, attaching a source, and tracking whether that source has finished ingestion. When a source is added it writes the row to Postgres and enqueues an ingestion job; it does not parse the source itself."}, "chat": {"d": "Runs one chat turn: retrieves relevant chunks for the question, builds a prompt from them, calls the model, and checks the answer stays grounded in what was retrieved. This is the piece that turns a notebook's sources into a citeable answer instead of an open-ended chat.", "links": [{"label": "Pattern: retrieval-augmented generation", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/rag"}]}, "art": {"d": "Accepts a request to generate something long-running, like an audio overview, replies immediately with a 202 and a job id, and starts a durable workflow to do the actual work. The client polls or listens for the workflow to finish rather than blocking on the request.", "links": [{"label": "Pattern: async job (202 and a job id)", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/async-job"}]}, "queue": {"d": "Holds one ingestion job per newly added source, decoupling the moment a user attaches a source from the slower work of parsing, chunking and embedding it. Workers pull from here at their own pace, so a burst of uploads doesn't stall the notebook service.", "links": [{"label": "Pattern: queue plus worker pool", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/worker-pool"}]}, "workers": {"d": "Pull jobs off the ingest queue and turn a raw source into retrievable chunks: parse the document, split it into chunks, and call the model gateway to embed each one. The output goes to the retrieval index, not back into Postgres."}, "index": {"d": "Holds both a vector index (semantic similarity) and a lexical index (BM25) over the same chunks, so a query can be matched by meaning or by exact keyword. The chat orchestrator queries this directly, then reranks the results before feeding them to the model.", "links": [{"label": "Pattern: hybrid retrieval and reranking", "url": "SYSTEM%20DESIGN.html#/patterns/search/hybrid-rerank"}]}, "model": {"d": "The single choke point for every call to a model, whatever it does: generate an answer, embed a chunk, rerank candidates, or synthesize speech. Centralizing it here is what makes it possible to log every call once, in one place, for tracing and cost control.", "links": [{"label": "Pattern: model routing and tiering", "url": "SYSTEM%20DESIGN.html#/patterns/llm-cost/routing"}]}, "workflow": {"d": "A durable, multi-step process for building an artifact like an audio overview: draft a script, call text-to-speech, assemble audio. Each step can be retried independently if it fails, so a transient TTS error doesn't mean redoing the whole thing.", "links": [{"label": "Pattern: durable workflow engine", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/workflow-engine"}]}, "blob": {"d": "Stores the bytes that don't belong in a relational database: the raw uploaded source files and the generated audio overviews. Postgres holds the metadata that points at these objects; the objects themselves are fetched directly by URL.", "links": [{"label": "Pattern: metadata in the database, bytes in object storage", "url": "SYSTEM%20DESIGN.html#/patterns/large-blobs/metadata-split"}]}, "trace": {"d": "Every call to the model gateway is logged here, which gives two things: a debugging trail for any single answer, and a corpus an offline eval suite can run against to check quality doesn't regress.", "links": [{"label": "Pattern: eval suites as release gates", "url": "SYSTEM%20DESIGN.html#/patterns/grounding/eval-gate"}]}}, "edges": {"client>gw": {"d": "Every client request, whatever kind, arrives here first over HTTPS."}, "gw>nb": {"d": "A source or notebook mutation is routed to the notebook service."}, "gw>chat": {"d": "A chat message is routed to the chat orchestrator."}, "gw>art": {"d": "A request to generate an artifact, like an audio overview, is routed to the artifact service."}, "nb>pg": {"d": "The notebook service reads and writes notebook and source rows."}, "chat>pg": {"d": "The chat orchestrator reads and appends to the conversation's chat history."}, "nb>queue": {"d": "When a source is added, the notebook service enqueues one ingestion job for it."}, "queue>workers": {"d": "An ingestion worker pulls the next job off the queue."}, "workers>model": {"d": "The worker calls the model gateway to embed each chunk it produced from the source."}, "workers>index": {"d": "The worker writes the parsed, chunked, embedded content into the retrieval index."}, "chat>index": {"d": "The chat orchestrator searches the retrieval index for chunks relevant to the current question."}, "chat>model": {"d": "The chat orchestrator sends the retrieved chunks and the question to the model to generate a grounded answer."}, "art>workflow": {"d": "The artifact service starts a durable workflow to build the requested artifact."}, "workflow>model": {"d": "The workflow calls the model gateway to draft the audio script, and again to synthesize speech from it."}, "workflow>blob": {"d": "The finished audio file is written to blob storage."}, "client>blob": {"d": "The client uploads a source's raw bytes directly to blob storage using a presigned URL, bypassing the API gateway for the large payload."}, "model>trace": {"d": "Every call through the model gateway, of any kind, is logged to traces for debugging and offline eval."}}, "walk": ["client", "client>gw", "gw", "gw>nb", "nb", "nb>pg", "pg", "nb>queue", "queue", "queue>workers", "workers", "workers>model", "model", "workers>index", "index", "client>blob", "blob", "gw>chat", "chat", "chat>pg", "chat>index", "chat>model", "gw>art", "art", "art>workflow", "workflow", "workflow>model", "workflow>blob", "model>trace", "trace"]},
  "sd:optimistic": {"nodes": {"ea": {"d": "Editor A, saving a change conditioned on the row still being at version 3 — the version A read.\n\nNo lock was taken while A was editing; optimistic concurrency assumes conflicts are rare and only checks for one at write time."}, "eb": {"d": "Editor B, who also read the row at version 3 and is now saving independently.\n\nB's write uses the same condition, `WHERE version = 3`, because that's the version B last saw, even though the row has since changed."}, "row": {"d": "The profile row, carrying an explicit version number that increments on every successful write.\n\nThis is the same atomic-conditional-update idea as a compare-and-swap, framed around an explicit version column instead of a status flag.", "links": [{"label": "Technique: atomic conditional update", "url": "SYSTEM%20DESIGN.html#/patterns/contention/atomic"}]}}, "edges": {"ea>row": {"d": "A's write matches `version = 3`, succeeds, and bumps the row to version 4."}, "eb>row": {"d": "B's write still says `WHERE version = 3`, but the row is now at version 4, so it matches zero rows — B's client has to reread and retry, seeing A's change."}}, "walk": ["ea", "eb", "ea>row", "row", "eb>row"]},
  "sd:orchestration": {"nodes": {"orch": {"d": "A single coordinator that calls each downstream service in turn and knows the whole sequence.\n\nThis is orchestration: control flow lives in one place, which makes the sequence easy to follow and easy to change, at the cost of that one place being a central dependency."}, "a1": {"d": "Service A, called directly by the orchestrator as step 1.\n\nIt has no idea it's part of a larger sequence — it just responds to the call it received."}, "a2": {"d": "Service B, called directly by the orchestrator as step 2, after A.\n\nLike A, it's a passive participant; the orchestrator is the one that knows both need to happen, and in what order."}, "b1": {"d": "Service C, shown on the choreography side of the diagram — it does not wait to be called.\n\nInstead of a coordinator invoking it, it acts on its own and then emits an event for whoever is listening."}, "b2": {"d": "Service D, which reacts to service C's event rather than being called directly.\n\nNo component here knows the full sequence; the behavior emerges from each service reacting to the last one's event. This is choreography, and it typically runs over a message broker.", "links": [{"label": "How the event usually travels: pub/sub fan-out", "url": "SYSTEM%20DESIGN.html#/patterns/real-time/pubsub"}]}}, "edges": {"orch>a1": {"d": "The orchestrator calls service A directly and waits on the result — synchronous, explicit control."}, "orch>a2": {"d": "The orchestrator then calls service B, again explicitly, continuing the sequence it owns."}, "b1>b2": {"d": "Service C emits an event asynchronously; service D picks it up on its own, with no direct call and no central coordinator involved."}}, "walk": ["orch", "orch>a1", "a1", "orch>a2", "a2", "b1", "b1>b2", "b2"]},
  "sd:outbox": {"nodes": {"api": {"d": "The service handling a request that needs to both change its own data and notify other services about it.\n\nThe hard problem this diagram solves: writing to the database and publishing an event are two different systems, and doing both reliably — not losing the event if the process crashes between the two — isn't trivial."}, "row": {"d": "The actual business data being changed, written in the same database transaction as the outbox row beside it.\n\nBecause both writes share one transaction, they either both happen or neither does — there's no window where the data changed but no event was recorded, or the reverse."}, "outboxrow": {"d": "A row written to an 'outbox' table, in the same transaction as the business row, recording that an event needs to be published.\n\nThis is the trick: instead of publishing directly to a broker, which can't participate in the database's transaction, record the intent to publish, transactionally, and let a separate process handle the actual send."}, "relay": {"d": "A separate process that polls the outbox table for unpublished rows and forwards them to the message broker.\n\nIt can fail and retry safely, because outbox rows aren't cleared until publish is confirmed — the source of truth for 'has this been published' lives in the table, not in the relay's memory.", "links": [{"label": "Same shape: queue plus worker pool", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/worker-pool"}, {"label": "Alternative: change data capture reads the DB log directly", "url": "SYSTEM%20DESIGN.html#/patterns/consistency/cdc"}]}, "broker": {"d": "The event broker or topic that other services actually subscribe to.\n\nDownstream consumers never see the outbox table directly — from their side, this looks like an ordinary published event.", "links": [{"label": "What happens after publish: pub/sub fan-out", "url": "SYSTEM%20DESIGN.html#/patterns/real-time/pubsub"}]}}, "edges": {"api>row": {"d": "The business row is written as part of a single database transaction."}, "api>outboxrow": {"d": "The outbox row recording the intent to publish is written in that same transaction, so it either commits with the business row or not at all."}, "relay>outboxrow": {"d": "The relay polls the outbox table separately, outside the original transaction, looking for rows it hasn't published yet."}, "relay>broker": {"d": "Once it finds an unpublished row, the relay publishes it to the broker, asynchronously, and only then marks it published."}}, "walk": ["api", "api>row", "row", "api>outboxrow", "outboxrow", "relay", "relay>outboxrow", "relay>broker", "broker"]},
  "sd:per-feature": {"nodes": {"write": {"d": "Write is any incoming change, before the service decides which consistency guarantee it actually needs."}, "svc": {"d": "Service is where the choice happens: it decides, per store, whether a write must be confirmed before returning or can be fired off in the background."}, "strong": {"d": "Booking DB gets strong consistency: the service waits for this write to commit before it's considered done, because a double-booking or a lost seat is unacceptable.", "links": [{"label": "Design: ticketmaster is strongly consistent for booking, eventual for search", "url": "SYSTEM%20DESIGN.html#/designs/ticketmaster/patterns"}]}, "eventual": {"d": "Search index gets eventual consistency: the service publishes the change and moves on without waiting, because being a few seconds stale in search results is an acceptable cost.", "links": [{"label": "Design: prior-auth's determinations are strongly consistent; reporting dashboards can lag", "url": "SYSTEM%20DESIGN.html#/designs/prior-auth/patterns"}]}}, "edges": {"write>svc": {"d": "A write reaches the service, which routes it differently depending on which downstream store it targets."}, "svc>strong": {"d": "The booking write is committed and the service waits for confirmation before returning; this call is on the critical path."}, "svc>eventual": {"d": "The search-index update is published without waiting for it to finish; the caller doesn't wait on this one."}}, "walk": ["write", "write>svc", "svc", "svc>strong", "strong", "svc>eventual", "eventual"]},
  "sd:pessimistic": {"nodes": {"txa": {"d": "The first transaction to reach the seat row, taking an explicit row lock with `SELECT ... FOR UPDATE`.\n\nIt now holds exclusive access until it commits or rolls back — no other transaction can modify or lock this row meanwhile."}, "row": {"d": "The seat row, held under an exclusive lock for the duration of transaction A.\n\nThis is a database-level version of the same idea as a distributed lock: block out every other writer instead of letting them race.", "links": [{"label": "Compare: distributed locks and leases with TTL", "url": "SYSTEM%20DESIGN.html#/patterns/contention/distributed-lock"}]}, "txb": {"d": "The second transaction, requesting the same row and finding it already locked.\n\nIt blocks and waits rather than failing immediately — it only proceeds once A releases the lock, and then sees whatever state A left behind."}}, "edges": {"txa>row": {"d": "Transaction A locks the row for update, guaranteeing nothing else can touch it until A finishes."}, "txb>row": {"d": "Transaction B's request for the same row has to wait — it doesn't fail or retry, it blocks until the lock frees up."}}, "walk": ["txa", "txa>row", "row", "txb", "txb>row"]},
  "sd:pg-fts": {"nodes": {"notes": {"d": "Notes table is the actual data: an ordinary Postgres table, with no separate search system involved."}, "tsvector": {"d": "tsvector column is a generated column, GIN-indexed, that Postgres derives automatically from the text columns; search happens against this, not the raw text directly."}, "query": {"d": "Query is a search term matched against the tsvector column using Postgres's own @@ match operator."}}, "edges": {"notes>tsvector": {"d": "The tsvector column is generated automatically from the table's text, kept current by Postgres itself as a generated column."}, "query>tsvector": {"d": "A search runs @@ against the tsvector column, which uses the GIN index instead of scanning text directly."}}, "walk": ["notes", "notes>tsvector", "tsvector", "query", "query>tsvector"]},
  "sd:policy-gate": {"nodes": {"action": {"d": "The proposed action is what an agent wants to do next, before any decision has been made about whether it's allowed to."}, "gate": {"d": "The policy gate turns a set of features about the action — what it affects, whether it's reversible, whether the input was tainted — into a verdict, deterministically. Given the same features, it always produces the same verdict; the risk judgment isn't left to the model's own discretion.", "links": [{"label": "Technique: tool effect classes", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/effect-classes"}]}, "allow": {"d": "Silent or notify covers low-risk actions: the gate lets them proceed on their own, at most telling the user afterward rather than asking beforehand."}, "ask": {"d": "Confirm or clarify covers higher-risk actions: the gate routes them to a human before they run, rather than deciding alone."}}, "edges": {"action>gate": {"d": "Every proposed action is evaluated by the gate before it can run."}, "gate>allow": {"d": "Low-risk actions are allowed to proceed, silently or with a notification, without waiting on a human."}, "gate>ask": {"d": "Riskier actions are routed to a human for confirmation or clarification before proceeding."}}, "walk": ["action", "action>gate", "gate", "gate>allow", "allow", "gate>ask", "ask"]},
  "sd:polling": {"nodes": {"client": {"d": "Asks the server for anything new on a fixed interval, whether or not anything has actually changed."}, "server": {"d": "Answers whatever the client asked, immediately, and closes the connection, whether the answer is nothing new or real data."}}, "edges": {"client>server": {"d": "The client sends a request on its polling interval."}, "server>client": {"d": "The server replies right away, even with an empty result, and the connection closes."}}, "walk": ["client", "client>server", "server", "server>client"]},
  "sd:presigned": {"nodes": {"client": {"d": "The uploader, which needs write access to object storage but should never hold the storage system's actual credentials.\n\nInstead, it asks the application for temporary, scoped permission."}, "api": {"d": "The file API, whose only involvement in the upload is authorizing it and generating a signed URL — the bytes never pass through it.\n\nThis keeps large file transfers off the application's own servers entirely, which is the main reason this pattern exists.", "links": [{"label": "Same principle: scoped, short-lived access", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/least-privilege"}]}, "storage": {"d": "Object storage, which accepts the upload directly from the client using nothing but the signed URL as proof of authorization.\n\nThe URL itself encodes the permission — which object, which operation, how long it's valid — so anyone holding it can use it until it expires, which is why its lifetime should be short."}}, "edges": {"client>api": {"d": "The client asks the API for permission to upload, before it has a URL to write to."}, "api>client": {"d": "The API returns a signed URL, scoped to this specific upload and time-limited."}, "client>storage": {"d": "The client uploads bytes directly to storage using the signed URL, bypassing the API tier entirely for the actual transfer."}}, "walk": ["client", "client>api", "api", "api>client", "client>storage", "storage"]},
  "sd:prior-auth:prior-authorization-validator-high-level": {"nodes": {"provider": {"d": "The hospital or clinic's own systems that submit a prior-authorization request: an electronic health record or a claims clearinghouse. They send the clinical record and the requested procedure, and later receive the decision back."}, "intake": {"d": "The entry point that accepts a request in whatever format the provider sends it: FHIR, the EDI 278 transaction standard, or a fax that gets OCR'd. It normalizes the request and stores the raw payload before anything else touches it."}, "raw": {"d": "An immutable, encrypted copy of exactly what the provider sent, kept before any parsing or interpretation. If a later stage misreads the request, this is the ground truth to check against, and it satisfies the audit requirement that nothing was altered on the way in."}, "wf": {"d": "Orchestrates a case from intake to decision. This is a regulated process with statutory deadlines, so it tracks timers per stage and retries failed steps rather than losing a case silently.", "links": [{"label": "Pattern: durable workflow engine", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/workflow-engine"}]}, "casedb": {"d": "The relational record of the case: status, timestamps, and links to every artifact produced along the way. The workflow reads and writes here at every stage transition."}, "rules": {"d": "A deterministic set of rules that answers two yes/no questions before any judgment is needed: is this member eligible, and does this procedure require prior authorization at all. Cases that fail here exit immediately, without reaching the model.", "links": [{"label": "Pattern: deterministic policy gate", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/policy-gate"}]}, "docs": {"d": "Extracts text from the clinical documents attached to the case and classifies each page (labs, notes, imaging report), so the criterion evaluator can find the right evidence instead of searching a whole PDF blindly."}, "evaluator": {"d": "Checks the clinical record against each coverage criterion in the policy, one at a time, and builds a timeline of what evidence supports or fails each one. It calls the model gateway to make the judgment call a rule can't, then hands every criterion's assessment to the decision gate."}, "model": {"d": "The model call boundary for this system, covered by a business associate agreement and configured for zero data retention, because the clinical record it sees is protected health information. It only ever answers the criterion evaluator's judgment calls; it never decides the case."}, "policy": {"d": "Holds the coverage criteria for every procedure, versioned so a decision can always be traced back to the exact policy text in effect on the day it was made."}, "gate": {"d": "A deterministic, code-only gate that turns the evaluator's assessments into one of three outcomes: approve, ask for more information, or route to a clinician. It has no path that lets the model deny a claim outright; a denial always goes through a human.", "links": [{"label": "Pattern: deterministic policy gate", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/policy-gate"}]}, "review": {"d": "A queue and UI where a licensed clinician makes the call the system won't make on its own: any case the gate can't approve or resolve with more information lands here, against a service-level deadline.", "links": [{"label": "Pattern: human confirmation and undo windows", "url": "SYSTEM%20DESIGN.html#/patterns/agent-safety/hitl-undo"}]}, "notify": {"d": "Sends the outcome back to the provider system in the same channel the request came in, always with the reason the criteria were or weren't met, not just a yes or no."}, "audit": {"d": "An append-only record of every decision and every override, and the evidence behind each: what regulators and internal review both check against, and the source data for building future eval sets.", "links": [{"label": "Pattern: event sourcing and append-only ledgers", "url": "SYSTEM%20DESIGN.html#/patterns/consistency/event-sourcing"}]}}, "edges": {"provider>intake": {"d": "The provider submits a request in whatever format their system produces."}, "intake>raw": {"d": "The raw payload is stored immutably before any parsing, so nothing can be lost or silently altered on the way in."}, "intake>wf": {"d": "A normalized request starts a new case workflow."}, "wf>casedb": {"d": "The workflow persists case status and stage transitions."}, "wf>rules": {"d": "The workflow checks eligibility and whether prior authorization is even required before doing any real evaluation work."}, "wf>docs": {"d": "The workflow sends attached clinical documents for OCR and classification."}, "wf>evaluator": {"d": "The workflow hands the case to the criterion evaluator once documents are processed."}, "evaluator>policy": {"d": "The evaluator fetches the versioned coverage criteria for the requested procedure."}, "evaluator>model": {"d": "The evaluator calls the model to judge whether the clinical evidence meets a criterion a rule can't check mechanically."}, "evaluator>gate": {"d": "The evaluator hands its per-criterion assessments to the decision gate."}, "gate>review": {"d": "Any case the gate can't approve outright, or resolve by asking for more information, is routed to a clinician."}, "gate>notify": {"d": "An approval, or a request for more information, goes straight to the provider response."}, "review>notify": {"d": "The clinician's decision becomes the response sent back to the provider."}, "gate>audit": {"d": "Every gate decision is logged with the evidence and criteria behind it."}, "review>audit": {"d": "Every clinician override or decision is logged to the audit trail."}, "notify>provider": {"d": "The decision and its stated reason are sent back to the provider's system."}}, "walk": ["provider", "provider>intake", "intake", "intake>raw", "raw", "intake>wf", "wf", "wf>casedb", "casedb", "wf>rules", "rules", "wf>docs", "docs", "wf>evaluator", "evaluator", "evaluator>policy", "policy", "evaluator>model", "model", "evaluator>gate", "gate", "gate>review", "review", "gate>notify", "review>notify", "notify", "gate>audit", "review>audit", "audit", "notify>provider"]},
  "sd:priority-cancel": {"nodes": {"high": {"d": "The queue for urgent work — the one a worker should always prefer if anything is waiting in it.\n\nDraining this queue first is what keeps latency-sensitive jobs from waiting behind a backlog of low-priority ones."}, "low": {"d": "The queue for work that can wait.\n\nIt's only served once the high-priority queue is empty, which means a sustained flood of high-priority jobs can starve it indefinitely without a fairness mechanism."}, "worker": {"d": "The process pulling from both queues, always checking high priority before low.\n\nIt also checks the cancel flag between steps of whatever job it's running, so a job can be stopped mid-flight rather than only before it starts."}, "cancel": {"d": "A flag or signal that a running job checks periodically to see if it's been asked to stop.\n\nBecause it's checked between steps rather than only at the start, a long job can be cancelled partway through instead of having to run to completion once started.", "links": [{"label": "A related cancellation point: checkpointing", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/checkpointing"}]}}, "edges": {"high>worker": {"d": "The worker drains the high-priority queue before touching low-priority work."}, "low>worker": {"d": "Only once high-priority work is exhausted does the worker pull from the low-priority queue."}, "worker>cancel": {"d": "Between steps of the job it's running, the worker checks whether cancellation has been requested."}}, "walk": ["high", "high>worker", "low", "low>worker", "worker", "worker>cancel", "cancel"]},
  "sd:prompt-cache": {"nodes": {"prefix": {"d": "The stable prefix is the part of a prompt that doesn't change between calls: system instructions, tool definitions, a long reference document. It's identical across many requests, which is exactly what makes it cacheable."}, "cache": {"d": "The prefix cache stores the model's internal representation of the stable prefix after the first time it's processed, so later calls sharing the same prefix don't pay to recompute it.\n\nMost providers charge a small write cost once and a much smaller read cost on every reuse, often a fraction of the normal input-token price. A long system prompt reused across thousands of requests turns from a per-call cost into a one-time cost."}, "suffix": {"d": "The new turn is whatever changes on every call — the user's latest message, a fresh tool result — appended after the cached prefix. It's the only part processed fresh every time."}, "model": {"d": "The model call combines the cached prefix with the new suffix, but pays full input-token price only for the suffix; the prefix is billed at the cached rate. For a request dominated by a large stable prefix, this is often the single biggest lever on cost.", "links": [{"label": "Lesson: prompt caching", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/11-llm-engineering/15-prompt-caching"}]}}, "edges": {"prefix>cache": {"d": "The first request pays to process the stable prefix, and the result is cached, keyed on the exact prefix content."}, "cache>model": {"d": "Every later call sharing that prefix reuses the cached version at a small fraction of its original cost."}, "suffix>model": {"d": "The new, variable part of the prompt is processed fresh and billed at full price on every call."}}, "walk": ["prefix", "prefix>cache", "cache", "suffix", "cache>model", "suffix>model", "model"]},
  "sd:pubsub": {"nodes": {"producer": {"d": "A service that emits an event once, without knowing or caring who is listening for it.\n\nIt does not track which connection servers need the update, or how many exist — that is the topic's job. In a chat room, this is typically the server that just handled the message a user sent."}, "topic": {"d": "A named channel, kept per room or per user, that a message broker uses to copy one published message out to every current subscriber.\n\nIt decouples the producer from the number and identity of consumers: publish once, and the broker (Redis pub/sub, Kafka, NATS) replicates it to whoever is subscribed right now. This is what lets a chat message reach everyone in a room without the sender knowing which server holds which connection.", "links": [{"label": "Technique: routing a room's clients to one owning server", "url": "SYSTEM%20DESIGN.html#/patterns/real-time/stateful-routing"}]}, "conn1": {"d": "One of possibly several websocket-holding servers that subscribed to this topic because it has at least one client from this room connected.\n\nIt receives every message published to the topic, then forwards only to its own locally connected clients."}, "conn2": {"d": "A second subscriber, on a different machine, holding a different subset of the room's connections.\n\nPub/sub's job is exactly this: get the same message to both conn1 and conn2 without the producer ever knowing either of them exists."}}, "edges": {"producer>topic": {"d": "The producer publishes the event exactly once; the broker takes on the job of copying it out to everyone subscribed."}, "topic>conn1": {"d": "The topic replicates the message to every subscribed connection server, including this one."}, "topic>conn2": {"d": "The same copy reaches this server too, in parallel with conn1 — fan-out to every subscriber, not delivery to a single consumer."}}, "walk": ["producer", "producer>topic", "topic", "topic>conn1", "conn1", "topic>conn2", "conn2"]},
  "sd:quadtree": {"nodes": {"root": {"d": "Root is a single node representing the entire mapped area before any splitting happens."}, "dense": {"d": "Dense quad is a region with enough points that it needs to be broken down further, so no one cell ends up holding too many items."}, "split": {"d": "4 sub-quads are what a dense quad becomes: it divides into four smaller quadrants, and any of those can itself split again if it's still dense."}, "sparse": {"d": "Sparse quad is a region with few points, so it stays large instead of subdividing — the whole point of a quadtree is that cell size adapts to density instead of being fixed."}}, "edges": {"root>dense": {"d": "A region found to be dense gets recursed into."}, "dense>split": {"d": "The dense region divides into four smaller quadrants."}, "root>sparse": {"d": "A region found to be sparse is left as one large cell, no further work needed."}}, "walk": ["root", "root>dense", "dense", "dense>split", "split", "root>sparse", "sparse"]},
  "sd:queue-buffer": {"nodes": {"producer": {"d": "Whatever generates work at a bursty, unpredictable rate."}, "queue": {"d": "Absorbs the burst, holding messages until a consumer is ready for them."}, "consumer": {"d": "Drains the queue at a steady rate it can actually sustain, regardless of how bursty the producers are."}}, "edges": {"producer>queue": {"d": "Producers write to the queue as fast as they generate work."}, "queue>consumer": {"d": "Consumers pull from the queue at their own steady, sustainable pace."}}, "walk": ["producer", "producer>queue", "queue", "queue>consumer", "consumer"]},
  "sd:quorum": {"nodes": {"writer": {"d": "Writer sends a write that must be acknowledged by W replicas before it's considered successful; here W=2."}, "reader": {"d": "Reader sends a read that must be answered by R replicas, here R=2, and takes the most recent value among what they return."}, "r1": {"d": "Replica 1 is one of three replicas in this set; whether it has the latest write on any given read is not guaranteed on its own."}, "r2": {"d": "Replica 2 happens to hold the latest write in this example: one of the two replicas the writer wrote to, and one of the two the reader queries, which is exactly why the overlap guarantees correctness."}, "r3": {"d": "Replica 3 is queried by the reader but was not one of the replicas written to; on its own it might be stale, which is why the reader needs R replicas' worth of answers, not just one."}}, "edges": {"writer>r1": {"d": "The write goes to replica 1, one of the two replicas required to acknowledge before the write counts as done."}, "writer>r2": {"d": "The write also goes to replica 2; together, replicas 1 and 2 satisfy W=2."}, "reader>r2": {"d": "The read queries replica 2, which happens to have the latest write."}, "reader>r3": {"d": "The read also queries replica 3; together, replicas 2 and 3 satisfy R=2, and because W+R (4) exceeds N (3), at least one queried replica is guaranteed to overlap with a written one."}}, "walk": ["writer", "writer>r1", "r1", "writer>r2", "r2", "reader", "reader>r2", "reader>r3", "r3"]},
  "sd:rag": {"nodes": {"q": {"d": "The question is the user's actual query, in natural language, before any search has happened against the source documents."}, "retrieve": {"d": "Retrieve searches the source store for passages relevant to the question and reranks the results, typically combining lexical search (keyword or BM25) with vector similarity so both exact terms and paraphrases are found.", "links": [{"label": "Lesson: RAG", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/11-llm-engineering/06-rag"}, {"label": "Lesson: advanced RAG", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/11-llm-engineering/07-advanced-rag"}]}, "src": {"d": "Sources are the documents split into chunks — small enough to fit several into a prompt, large enough to keep a claim's context intact."}, "gen": {"d": "Generate is instructed to answer only from the numbered passages it was handed, not from what it might already know about the topic. Numbering the passages is what makes citation-by-number possible later."}}, "edges": {"q>retrieve": {"d": "The raw question drives the search; no generation happens before retrieval runs."}, "retrieve>src": {"d": "Retrieval fetches candidate chunks from the source store."}, "retrieve>gen": {"d": "Only the retrieved passages, not the whole source store, are handed to generation, numbered for reference."}}, "walk": ["q", "q>retrieve", "retrieve", "retrieve>src", "src", "retrieve>gen", "gen"]},
  "sd:rate-limiting": {"nodes": {"client": {"d": "Client is any caller of the service, trusted or not; the limiter tracks each client's rate independently."}, "limiter": {"d": "Rate limiter enforces a cap, here a token bucket per user, on how fast any one client can call in; it decides before the request ever reaches the real service."}, "svc": {"d": "Service is the actual backend, protected from being overwhelmed by any single caller because the limiter already filtered excess requests."}}, "edges": {"client>limiter": {"d": "Every request passes through the limiter before it can reach the service."}, "limiter>svc": {"d": "A request still under the caller's limit is let through."}, "limiter>client": {"d": "A request over the limit is rejected immediately; the caller never reaches the service at all."}}, "walk": ["client", "client>limiter", "limiter", "limiter>svc", "svc", "limiter>client"]},
  "sd:read-your-writes": {"nodes": {"user": {"d": "User just wrote something and immediately reads it back in the same flow — the exact case this technique protects against."}, "router": {"d": "Read router tracks whether the current user has a very recent write and decides where to send their next read based on that, not on a fixed rule."}, "primary": {"d": "Primary (or a replica confirmed to be caught up) is where the router sends a read when it knows the reader just wrote something, so the reader is guaranteed to see it."}, "replica": {"d": "Replica may lag, and that's fine for any reader who isn't asking about their own just-made change.", "links": [{"label": "Session: Caching, then putting it together", "url": "index.html#/s/5/1"}]}}, "edges": {"user>router": {"d": "A user writes, then immediately reads; this sequence is exactly what would otherwise expose replica lag as a bug."}, "router>primary": {"d": "If the router knows this user just wrote, it routes the read to the primary, or a replica it knows is caught up, instead of the default."}, "router>replica": {"d": "For everyone else, with no recent write of their own, reads take the cheaper default path to the replica."}}, "walk": ["user", "user>router", "router", "router>primary", "primary", "router>replica", "replica"]},
  "sd:real-time:push-path": {"nodes": {"client": {"d": "Whoever is holding an open connection waiting for something to happen, rather than asking again and again."}, "conn": {"d": "The servers that actually keep a client's connection open, whether that's an SSE stream or a WebSocket. This is what makes real-time push architecturally different from a normal stateless request: a specific server now holds specific state for a specific client.", "links": [{"label": "Technique: stateful servers with consistent hashing", "url": "SYSTEM%20DESIGN.html#/patterns/real-time/stateful-routing"}]}, "registry": {"d": "Tracks which connection server currently holds which user's connection, so a message meant for that user can be routed to the right server instead of broadcast to all of them.", "links": [{"label": "Technique: stateful servers with consistent hashing", "url": "SYSTEM%20DESIGN.html#/patterns/real-time/stateful-routing"}]}, "log": {"d": "Every event is appended here with an offset, so a client that reconnects after a dropped connection can ask for everything since the offset it last saw, instead of losing events.", "links": [{"label": "Technique: resumable streams", "url": "SYSTEM%20DESIGN.html#/patterns/real-time/resumable"}]}, "pubsub": {"d": "Fans a published event out to every connection server that has a subscriber for its topic, whether that topic is a chat room or a single user.", "links": [{"label": "Technique: pub/sub fan-out", "url": "SYSTEM%20DESIGN.html#/patterns/real-time/pubsub"}]}, "producer": {"d": "Whatever generates the event in the first place: a database write, a background job finishing, a model streaming tokens."}}, "edges": {"producer>pubsub": {"d": "A producer publishes an event to its topic."}, "pubsub>conn": {"d": "Pub/sub fans the event out to every connection server subscribed to that topic."}, "conn>client": {"d": "The connection server pushes the event down the client's open connection."}, "conn>registry": {"d": "A connection server registers which user it's currently holding a connection for."}, "producer>log": {"d": "The same event is appended to the durable event log."}, "conn>log": {"d": "A reconnecting client's connection server replays from the log starting at the last offset it saw."}}, "walk": ["producer", "producer>pubsub", "pubsub", "pubsub>conn", "conn", "conn>client", "client", "conn>registry", "registry", "producer>log", "log", "conn>log"]},
  "sd:refusal": {"nodes": {"q": {"d": "The question is what's asked, before it's known whether the available sources actually contain an answer to it."}, "gen": {"d": "Generate checks whether the evidence it has actually supports an answer, and produces one of two outcomes: a cited answer, or an explicit refusal, rather than guessing when the evidence is thin."}, "answer": {"d": "The answer is returned with citations when there was evidence to support it."}, "refuse": {"d": "Not in sources is a refusal: an explicit statement that the answer isn't in the available material. It is treated as a correct, valid outcome, not a failure of the system, because a wrong guess would be worse.", "links": [{"label": "Lesson: guardrails", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/11-llm-engineering/12-guardrails"}]}}, "edges": {"q>gen": {"d": "The question goes to generation, which decides whether it can be answered from evidence at all."}, "gen>answer": {"d": "When evidence supports a claim, an answer with citations is produced."}, "gen>refuse": {"d": "When no evidence supports an answer, generation refuses instead of guessing."}}, "walk": ["q", "q>gen", "gen", "gen>answer", "answer", "gen>refuse", "refuse"]},
  "sd:reliability:failing-safely": {"nodes": {"client": {"d": "Clients are whatever sends traffic in: end users, other services, anything external to this system."}, "gw": {"d": "Gateway is the front door: it enforces rate limits and checks health before anything reaches a service replica, so an overloaded or unhealthy backend never even sees the excess traffic.", "links": [{"label": "Technique: rate limiting", "url": "SYSTEM%20DESIGN.html#/patterns/reliability/rate-limiting"}]}, "flags": {"d": "Flags + monitors is config-driven control over the running system: percentage rollouts and kill switches that change behavior without a deploy, plus alerts that catch failures which never raise an error on their own.", "links": [{"label": "Technique: feature flags and kill switches", "url": "SYSTEM%20DESIGN.html#/patterns/reliability/flags"}]}, "svc": {"d": "Service replicas are multiple stateless instances spread across zones, so any one instance, or one zone, failing doesn't take the whole service down."}, "cb": {"d": "Circuit breaker sits between the service and a risky dependency: it applies a timeout to each call, backs off on repeated failure, and eventually stops calling that dependency at all until it recovers.", "links": [{"label": "Technique: circuit breaker", "url": "SYSTEM%20DESIGN.html#/patterns/reliability/circuit-breaker"}]}, "fallback": {"d": "Fallback is what gets served when the breaker is open: a stale cached value or a sane default, so the caller gets something instead of an error."}, "dep": {"d": "Dependency is an external or downstream system that this diagram assumes can be slow or fully down at any time — reliability design starts from that assumption, not from trusting it."}, "db": {"d": "Primary + standby is the database layer: a primary that takes writes and a standby ready to be promoted automatically if the primary fails.", "links": [{"label": "Technique: replication and failover", "url": "SYSTEM%20DESIGN.html#/patterns/reliability/replication-failover"}]}, "backup": {"d": "Backups are periodic snapshots of the database, kept for point-in-time restore — the last line of defense against data loss or corruption that replication alone can't undo, since a bad write replicates too.", "links": [{"label": "Technique: multi-region and backups", "url": "SYSTEM%20DESIGN.html#/patterns/reliability/multi-region"}]}}, "edges": {"client>gw": {"d": "All external traffic enters through the gateway first, before it reaches any service replica."}, "gw>svc": {"d": "Requests that pass rate-limit and health checks are routed to a healthy replica."}, "flags>svc": {"d": "Flag config dials the service's behavior live, a percentage rollout or a kill switch, without redeploying it."}, "svc>cb": {"d": "Any call the service makes to a risky dependency goes through the breaker first."}, "cb>dep": {"d": "The breaker calls the dependency directly, but bounds the wait with a timeout."}, "cb>fallback": {"d": "Once the breaker has opened after too many recent failures, it skips the dependency entirely and returns the fallback instead."}, "svc>db": {"d": "The service's writes go to the primary, which the standby keeps in sync with automatically."}, "db>backup": {"d": "The database is snapshotted periodically, independent of the standby, to protect against a bad write that has already replicated."}}, "walk": ["client", "client>gw", "gw", "gw>svc", "flags", "flags>svc", "svc", "svc>cb", "cb", "cb>dep", "dep", "cb>fallback", "fallback", "svc>db", "db", "db>backup", "backup"]},
  "sd:replicas": {"nodes": {"writer": {"d": "Whatever performs a write to the database."}, "primary": {"d": "The only database that accepts writes; every write, from any writer, goes here first."}, "replica": {"d": "A copy of the primary kept current by asynchronous replication. Because replication is asynchronous, it can be some fraction of a second, or more under load, behind the primary."}, "reader": {"d": "Whatever performs a read; here, it reads only from the replica, never the primary."}}, "edges": {"writer>primary": {"d": "A write goes to the primary."}, "primary>replica": {"d": "The primary streams its writes to the replica asynchronously."}, "reader>replica": {"d": "Reads are served from the replica, not the primary."}}, "walk": ["writer", "writer>primary", "primary", "primary>replica", "replica", "reader", "reader>replica"]},
  "sd:replication-failover": {"nodes": {"app": {"d": "App is whatever issues the write, with no need to know which replica currently holds the primary role."}, "primary": {"d": "Primary is the database that accepts writes and only acknowledges one once it's durable — the definition of a leader in a leader-follower setup."}, "standby": {"d": "Standby is a synchronous replica of the primary, kept close enough that it can safely take over without losing the write that was just acknowledged."}}, "edges": {"app>primary": {"d": "The app sends its write to whichever node currently holds the primary role."}, "primary>standby": {"d": "The write is replicated synchronously before the primary acknowledges it back to the app — this is what makes promotion safe."}, "standby>app": {"d": "If the primary fails, the standby is promoted and the app is redirected to it; failover itself takes time and isn't instantaneous, which is why this edge is drawn asynchronous."}}, "walk": ["app", "app>primary", "primary", "primary>standby", "standby", "standby>app"]},
  "sd:reservation": {"nodes": {"buyer": {"d": "The person putting a temporary claim on a seat before paying, so it can't be sold to anyone else while checkout is in progress.\n\nThis buys time for payment without holding the seat under a full pessimistic lock for however long checkout takes."}, "hold": {"d": "A time-boxed claim on the seat — a lease — good for a fixed window (10 minutes) rather than forever.\n\nIf the buyer pays inside that window, the hold becomes a real booking; if the window runs out first, the seat quietly becomes available again with no action needed from anyone.", "links": [{"label": "Technique: leases, heartbeats and visibility timeouts", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/leases"}]}, "seat": {"d": "The seat itself, which flips between held, confirmed, and available again depending on what happens to the hold.\n\nThis is the resource the whole contention problem is about — every other node here exists to decide who gets to move this one into confirmed."}}, "edges": {"buyer>hold": {"d": "The buyer reserves the seat, starting the hold's countdown before any payment has happened."}, "hold>seat": {"d": "The hold resolves one of two mutually exclusive ways: payment succeeds and the seat becomes confirmed, or the hold's TTL runs out first and the seat is released back to available, asynchronously, with no buyer action required."}}, "walk": ["buyer", "buyer>hold", "hold", "hold>seat", "seat"]},
  "sd:response-cache": {"nodes": {"req": {"d": "The request is the incoming question or task, before it's known whether an equivalent one has been answered before."}, "cache": {"d": "The response cache stores full answers, keyed either by an exact hash of the request (identical text) or by an embedding of it (semantically similar text). A semantic hit means a differently worded but equivalent question can still be served from cache.", "links": [{"label": "Lesson: caching and cost", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/11-llm-engineering/11-caching-cost"}]}, "model": {"d": "The model only runs on a cache miss — when neither an exact nor a close-enough prior answer exists."}}, "edges": {"req>cache": {"d": "Every request is looked up in the cache first, by exact hash or by embedding similarity."}, "cache>model": {"d": "A miss — no exact or close-enough match — falls through to the model."}, "model>cache": {"d": "The model's answer is written back into the cache, so a future equivalent request can hit it instead of calling the model again."}}, "walk": ["req", "req>cache", "cache", "cache>model", "model", "model>cache"]},
  "sd:resumable": {"nodes": {"client": {"d": "The consumer that dropped its connection and is reconnecting, carrying the id (offset) of the last event it definitely received.\n\nThat id is the whole trick: without it, the server has no way to know what the client already saw, and would have to replay everything or nothing."}, "server": {"d": "The service that owns the stream and knows how to translate a client's last-seen id into a position in the log.\n\nIt does not need to remember anything about a specific client between requests; the log itself is the memory.", "links": [{"label": "How the right server gets reached again: stateful routing", "url": "SYSTEM%20DESIGN.html#/patterns/real-time/stateful-routing"}]}, "log": {"d": "An append-only event log that keeps every event at a stable offset, so any past position can be re-read on demand.\n\nThis is the same structure event sourcing relies on: the log, not a snapshot, is the source of truth, and offsets are what make 'replay from here' possible.", "links": [{"label": "Technique: event sourcing (the log as source of truth)", "url": "SYSTEM%20DESIGN.html#/patterns/consistency/event-sourcing"}]}}, "edges": {"client>server": {"d": "The client reconnects and states the last event id it processed, instead of starting cold."}, "server>log": {"d": "The server seeks to that offset in the log rather than replaying from the beginning."}, "server>client": {"d": "Everything after that offset streams back asynchronously — the client keeps whatever session state it already had while the missed events arrive as a batch."}}, "walk": ["client", "client>server", "server", "server>log", "log", "server>client"]},
  "sd:resumable-events": {"nodes": {"viewer": {"d": "The viewer reconnects after a disconnect — a dropped WebSocket, a browser tab that went to sleep, a network blip — and needs to pick up exactly where it left off, not from the beginning and not by missing events in between."}, "stream": {"d": "The event log retains events with stable ids for long enough that a reconnecting viewer can ask for everything since the last one it saw. Without retained ids, a disconnect would mean either replaying from scratch or silently losing whatever happened while disconnected.", "links": [{"label": "Technique: resumable streams (real-time pattern)", "url": "SYSTEM%20DESIGN.html#/patterns/real-time/resumable"}]}}, "edges": {"viewer>stream": {"d": "On reconnect, the viewer tells the stream the id of the last event it actually received."}, "stream>viewer": {"d": "The stream replays every event after that id, asynchronously, until the viewer is caught up to live."}}, "walk": ["viewer", "viewer>stream", "stream", "stream>viewer"]},
  "sd:retries-dlq": {"nodes": {"worker": {"d": "The process attempting to execute the job.\n\nEvery attempt is tracked against the same job, incrementing an attempt counter each time."}, "job": {"d": "The unit of work, carrying its current attempt number.\n\nA failed job isn't immediately abandoned or immediately retried at full speed — its outcome depends on the attempt count and the backoff policy."}, "backoff": {"d": "The delay applied before the next retry, growing exponentially and randomized with jitter so retries from many failed jobs don't all land at the same instant and overload the same downstream dependency.\n\nJitter specifically prevents a thundering herd of synchronized retries.", "links": [{"label": "Technique: timeouts and retries", "url": "SYSTEM%20DESIGN.html#/patterns/reliability/timeouts-retries"}]}, "dlq": {"d": "Where the job goes once it has failed enough times that retrying further isn't worth it.\n\nThis caps the cost of a job that will never succeed, and gives a human a queue to inspect instead of an infinite retry loop.", "links": [{"label": "Reading: dead-letter queues for error handling (Conduktor)", "url": "https://www.conduktor.io/glossary/dead-letter-queues-for-error-handling"}]}}, "edges": {"worker>job": {"d": "The worker makes an attempt at the job."}, "job>backoff": {"d": "A failed attempt schedules a retry, but only after a backoff delay rather than immediately."}, "backoff>worker": {"d": "Once the backoff delay elapses, the job is retried as attempt N+1."}, "job>dlq": {"d": "After the job has failed N times, it stops being retried and moves to the dead-letter queue instead."}}, "walk": ["worker", "worker>job", "job", "job>backoff", "backoff", "backoff>worker", "job>dlq", "dlq"]},
  "sd:routing": {"nodes": {"req": {"d": "The request is the incoming task before any decision has been made about which model should handle it."}, "small": {"d": "The small model's first job here isn't to answer — it's to classify how hard the request is, using a cheap, fast model built for triage rather than open-ended generation.", "links": [{"label": "Lesson: structured outputs", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/11-llm-engineering/03-structured-outputs"}]}, "large": {"d": "The large model handles requests the small model judged too hard for itself: multi-step reasoning, long-form writing, anything where a wrong shortcut is expensive."}, "answer": {"d": "The answer is the final output returned to the caller, regardless of which model tier actually produced it."}}, "edges": {"req>small": {"d": "The small model receives the raw request first, in a triage role, not to generate the real answer."}, "small>answer": {"d": "Requests the small model classifies as easy get answered directly, by the small model, without escalating."}, "small>large": {"d": "Requests classified as hard are handed to the large model instead of being answered by the classifier."}, "large>answer": {"d": "The large model's response becomes the final answer."}}, "walk": ["req", "req>small", "small", "small>answer", "small>large", "large", "large>answer", "answer"]},
  "sd:saga": {"nodes": {"s1": {"d": "Step 1: reserve, running as an independent service that emits an event when it finishes.\n\nThere is no orchestrator here — s1 doesn't call s2 directly, it just announces that it's done."}, "s2": {"d": "Step 2: charge, triggered by step 1's event rather than by a coordinator.\n\nIt's listening for exactly the event s1 emits; this is choreography, the event-driven alternative to orchestration.", "links": [{"label": "Contrast: orchestration versus choreography", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/orchestration"}]}, "s3": {"d": "Step 3, which fails after being triggered by step 2's event.\n\nIts failure is itself an event, 'failed', that something downstream needs to be listening for."}, "comp": {"d": "A compensator that listens for failure events anywhere in the chain and runs the matching undo.\n\nBecause there's no central coordinator, the compensator has to infer, from the event alone, what already succeeded and needs undoing — here, step 1's reservation.", "links": [{"label": "Compare: two-phase commit versus sagas", "url": "SYSTEM%20DESIGN.html#/patterns/contention/cross-service"}]}}, "edges": {"s1>s2": {"d": "Step 1 finishing emits an event that step 2 is listening for — no direct call."}, "s2>s3": {"d": "Step 2 finishing emits its own event, which step 3 picks up."}, "s3>comp": {"d": "Step 3's failure is an event that the compensator is listening for."}, "comp>s1": {"d": "The compensator runs step 1's undo — release the reservation — since step 1 succeeded but the overall saga did not."}}, "walk": ["s1", "s1>s2", "s2", "s2>s3", "s3", "s3>comp", "comp", "comp>s1"]},
  "sd:scaling-reads:read-path-progression": {"nodes": {"client": {"d": "Whoever is reading, at a ratio the sub-label calls out directly: for every write, this system sees ten to a hundred reads. That ratio is why almost everything else in this diagram exists."}, "cdn": {"d": "Serves static assets and hot, cacheable pages straight from the edge, without the request ever reaching an app server.", "links": [{"label": "Technique: CDN and edge caching", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-reads/cdn"}]}, "app": {"d": "Runs the cache-aside logic itself: check the cache first, and only fall through to the database on a miss.", "links": [{"label": "Technique: cache-aside (Redis)", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-reads/cache-aside"}]}, "cache": {"d": "Holds recently-read data with a TTL so it eventually expires on its own, and coalesces concurrent misses on the same key so a hundred simultaneous cache misses don't turn into a hundred identical database queries.", "links": [{"label": "Technique: hot-key handling", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-reads/hot-keys"}]}, "replicas": {"d": "Copies of the primary database that only serve reads, kept current by asynchronous replication, which means they can be a little behind the primary at any given moment.", "links": [{"label": "Technique: read replicas", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-reads/replicas"}]}, "primary": {"d": "The one database that accepts writes, tuned with indexes and denormalized fields specifically to keep its own read cost down for the reads that still land here.", "links": [{"label": "Technique: indexing and query tuning", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-reads/indexing"}]}, "cdc": {"d": "Captures every change to the primary and turns it into a stream of events, used here to tell the cache which keys just went stale.", "links": [{"label": "Technique: cache invalidation", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-reads/invalidation"}]}}, "edges": {"client>cdn": {"d": "A request for a static or hot page is served from the CDN."}, "client>app": {"d": "Anything dynamic reaches an app server."}, "app>cache": {"d": "The app server checks the cache first."}, "app>replicas": {"d": "On a cache miss, the app server reads from a replica instead of the primary."}, "app>primary": {"d": "All writes go to the primary, never a replica."}, "primary>replicas": {"d": "The primary asynchronously replicates its writes out to the replicas."}, "primary>cdc": {"d": "The primary emits its changes to the change stream."}, "cdc>cache": {"d": "The change stream tells the cache to evict keys that just went stale."}}, "walk": ["client", "client>cdn", "cdn", "client>app", "app", "app>cache", "cache", "app>replicas", "replicas", "app>primary", "primary", "primary>replicas", "primary>cdc", "cdc", "cdc>cache"]},
  "sd:scaling-writes:write-path-under-load": {"nodes": {"client": {"d": "Whoever is writing, at a rate that spikes rather than staying steady."}, "admit": {"d": "The first check on a write: enforces a rate limit and sheds load outright if the system is already overwhelmed, rather than letting every write through and falling over.", "links": [{"label": "Technique: load shedding and backpressure", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-writes/load-shedding"}]}, "buffer": {"d": "Absorbs a burst of admitted writes so downstream writers can process them at a steady pace instead of the burst's actual arrival rate.", "links": [{"label": "Technique: queue buffering", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-writes/queue-buffer"}]}, "writers": {"d": "Consume from the buffer, group writes together, and flush them in batches rather than one write per request.", "links": [{"label": "Technique: batching and write-behind", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-writes/batching"}]}, "s1": {"d": "Holds the slice of keys that hash into range A.", "links": [{"label": "Technique: horizontal sharding", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-writes/sharding"}]}, "s2": {"d": "Holds the slice of keys that hash into range B."}, "s3": {"d": "Holds a key so hot that even its own shard needed salting, splitting the one key into several sub-keys so it doesn't become a hot partition on its own shard.", "links": [{"label": "Technique: hot-partition fixes (salting)", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-writes/hot-partition"}]}}, "edges": {"client>admit": {"d": "Writes hit admission control first."}, "admit>buffer": {"d": "An admitted write is placed on the write buffer."}, "buffer>writers": {"d": "Batch writers consume from the buffer at their own pace."}, "writers>s1": {"d": "A write for a range-A key goes to shard 1."}, "writers>s2": {"d": "A write for a range-B key goes to shard 2."}, "writers>s3": {"d": "A write for the hot key goes to shard 3, where it's further salted."}}, "walk": ["client", "client>admit", "admit", "admit>buffer", "buffer", "buffer>writers", "writers", "writers>s1", "s1", "writers>s2", "s2", "writers>s3", "s3"]},
  "sd:scan": {"nodes": {"client": {"d": "Client sends the same kind of 'near me' query as any geo search: a location and a radius."}, "svc": {"d": "Search service here does no indexing at all: it is the naive baseline the other geo techniques exist to replace."}, "all": {"d": "All items is the entire dataset, scanned linearly: distance is computed to every single item, so the query cost is proportional to the dataset's size."}}, "edges": {"client>svc": {"d": "A location and radius arrive with no shortcut available for the service to take."}, "svc>all": {"d": "Every item's distance from the query point is computed, one by one."}}, "walk": ["client", "client>svc", "svc", "svc>all", "all"]},
  "sd:search:hybrid-search": {"nodes": {"query": {"d": "Query is what the user actually typed: text plus any structured filters, like date or category."}, "api": {"d": "Search API parses the query and fans it out to both retrieval methods at once; it doesn't pick one or the other, it uses both and merges the results."}, "inv": {"d": "Inverted index (BM25, filters) is the keyword side: fast, exact-term matching and filtering, kept in sync with the source database via CDC.", "links": [{"label": "Technique: inverted index", "url": "SYSTEM%20DESIGN.html#/patterns/search/inverted"}, {"label": "Technique: change data capture (how this index stays in sync)", "url": "SYSTEM%20DESIGN.html#/patterns/consistency/cdc"}]}, "vec": {"d": "Vector index (HNSW, embedded on CDC) is the semantic side: finds passages whose meaning is close to the query even if they share no exact words, using an approximate nearest-neighbor structure.", "links": [{"label": "Technique: vector index", "url": "SYSTEM%20DESIGN.html#/patterns/search/vector"}]}, "src": {"d": "Source DB is where the underlying records actually live; the inverted index is a derived copy of it, not the other way around."}, "fuse": {"d": "Fuse + rerank combines the keyword and vector result lists via reciprocal rank fusion, then reorders the merged list with a more expensive cross-encoder model before returning the final top K.", "links": [{"label": "Technique: hybrid retrieval and reranking", "url": "SYSTEM%20DESIGN.html#/patterns/search/hybrid-rerank"}]}}, "edges": {"query>api": {"d": "The raw query, text and filters, arrives at the API."}, "api>inv": {"d": "The API fans the query out to the keyword index, in parallel with the vector search."}, "api>vec": {"d": "The API also fans the query out to the vector index, embedding it first."}, "inv>fuse": {"d": "Keyword results feed into the fusion step alongside vector results."}, "vec>fuse": {"d": "Vector results feed into the same fusion step."}, "fuse>api": {"d": "The final, reranked top-K list is returned to the API to send back."}, "src>inv": {"d": "The keyword index is kept current by tailing changes from the source database via CDC, not by the search API writing to it directly."}}, "walk": ["query", "query>api", "api", "api>inv", "inv", "api>vec", "vec", "src", "src>inv", "inv>fuse", "vec>fuse", "fuse", "fuse>api"]},
  "sd:shadow-online": {"nodes": {"traffic": {"d": "Real traffic is actual user requests, as they happen, not a replayed or synthetic test set."}, "prod": {"d": "Production is the current live system, whose output actually reaches the user and takes effect."}, "shadow": {"d": "The candidate is a new version — different model, prompt, or pipeline — run on a mirrored copy of the same traffic, but its output never reaches the user and never takes effect. It exists purely to be measured against production."}, "signals": {"d": "Online signals are real-world outcomes that indicate quality without needing a labeled eval set: users hitting undo, giving a thumbs-down, abandoning a session. Both production and the candidate are compared against these signals."}}, "edges": {"traffic>prod": {"d": "Live traffic is served by production, whose responses actually reach the user."}, "traffic>shadow": {"d": "The same traffic is mirrored to the candidate asynchronously, off the response path, so shadowing adds no latency for the user."}, "shadow>signals": {"d": "The candidate's output is compared against outcome signals for measurement only; it never influences what the user actually sees."}, "prod>signals": {"d": "Production's real outcomes are the baseline the candidate is measured against."}}, "walk": ["traffic", "traffic>prod", "prod", "traffic>shadow", "shadow", "shadow>signals", "prod>signals", "signals"]},
  "sd:sharding": {"nodes": {"writer": {"d": "Whoever is writing, indifferent to which shard actually ends up storing the row."}, "router": {"d": "Decides which shard owns a given write by hashing its key, the one piece of logic that has to agree everywhere a write or read for that key happens."}, "shardA": {"d": "One of several independent stores, holding only the slice of keys that hash to it."}, "shardB": {"d": "Another independent store, holding a different slice of the key space."}}, "edges": {"writer>router": {"d": "Every write goes through the router first."}, "router>shardA": {"d": "A key that hashes into A's range is written there."}, "router>shardB": {"d": "A key that hashes into B's range is written there."}}, "walk": ["writer", "writer>router", "router", "router>shardA", "shardA", "router>shardB", "shardB"]},
  "sd:single-writer": {"nodes": {"queue": {"d": "A queue partitioned by key, so every message for a given key always lands on the same partition, in order.\n\nPartitioning is what makes 'single writer' possible without a lock: if only one consumer ever reads a given partition, writes for that key arrive already serialized.", "links": [{"label": "Alternative implementation: queue claiming with SKIP LOCKED", "url": "SYSTEM%20DESIGN.html#/patterns/contention/claim-skip-locked"}]}, "owner": {"d": "The one process assigned to consume this key's partition — by construction, no other process is also consuming it.\n\nThis is the same shape as a stateful server owning a chat room: one owner, so there's nothing to coordinate between competing writers.", "links": [{"label": "Same idea: routing all of a key's traffic to one owning server", "url": "SYSTEM%20DESIGN.html#/patterns/real-time/stateful-routing"}]}, "resource": {"d": "The underlying data the owner writes to.\n\nBecause only the owner ever writes it, writes arrive already serialized — there is no possibility of two writers racing on the same key."}}, "edges": {"queue>owner": {"d": "Messages for this key are delivered only to the process designated as its owner — never to any other consumer."}, "owner>resource": {"d": "The owner applies writes to the resource one at a time, in the order it received them, with no other writer to race against."}}, "walk": ["queue", "queue>owner", "owner", "owner>resource", "resource"]},
  "sd:sse": {"nodes": {"server": {"d": "Holds the connection open and pushes events down it whenever it has something new, without the client asking again."}, "client": {"d": "Keeps the last event id it saw, so if the connection drops and it reconnects, it can tell the server exactly where to resume from.", "links": [{"label": "Technique: resumable streams", "url": "SYSTEM%20DESIGN.html#/patterns/real-time/resumable"}]}}, "edges": {"server>client": {"d": "The server streams events down the open connection as they happen, in one direction only."}}, "walk": ["server", "server>client", "client"]},
  "sd:state-machine": {"nodes": {"proposed": {"d": "A state a record can be in, `proposed`, before whatever transition is being attempted.\n\nStates are named explicitly rather than inferred from a combination of boolean flags, which is the point of modeling this as a state machine at all."}, "guard": {"d": "The check that decides whether a requested transition is one of the legal moves out of the current state.\n\nThis is what stops, for instance, jumping straight from `proposed` to a finished state, skipping steps that must happen in between — only transitions the machine explicitly allows are permitted.", "links": [{"label": "Often embedded inside: durable workflow engine", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/workflow-engine"}]}, "pending": {"d": "The state `pending_confirm`, reached only via a transition the guard approved.\n\nEvery state in a well-designed machine like this should be reachable only through an explicit, legal transition — never by, say, directly setting a status column."}, "blocked": {"d": "The outcome when a requested transition isn't in the allowed set for the current state — for instance, an attempt to skip a required step.\n\nRejecting it here, at the guard, is cheaper and safer than letting an invalid state combination exist somewhere downstream and discovering it later."}}, "edges": {"proposed>guard": {"d": "A transition out of `proposed` is requested and checked before it's allowed to happen."}, "guard>pending": {"d": "The requested transition is on the machine's allowed list, so the record moves to `pending_confirm`."}, "guard>blocked": {"d": "The requested transition isn't legal from this state (for example, trying to skip a step), so it's rejected instead of silently applied."}}, "walk": ["proposed", "proposed>guard", "guard", "guard>pending", "pending", "guard>blocked", "blocked"]},
  "sd:stateful-routing": {"nodes": {"clients": {"d": "Every client currently in room X — potentially dozens or thousands of separate websocket connections.\n\nThey all need to land on the same backend process, because that process holds the room's live, in-memory state (who's typing, current game state, and so on)."}, "router": {"d": "A layer in front of the servers that decides which server owns room X, typically by hashing the room id.\n\nBecause the hash is deterministic, the same room always maps to the same server — this is what makes the routing sticky without a lookup table for every room. It is the same idea as consistent hashing used for sharding data, applied here to routing connections instead.", "links": [{"label": "Technique: consistent hashing", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-writes/consistent-hashing"}]}, "server": {"d": "The one backend process that currently owns room X's in-memory state — the source of truth while the room is active.\n\nIf this server restarts or crashes, every client it was serving needs a way to reconnect and catch up on whatever they missed, which is what resumable streams solve.", "links": [{"label": "Technique: resumable streams after reconnect", "url": "SYSTEM%20DESIGN.html#/patterns/real-time/resumable"}]}}, "edges": {"clients>router": {"d": "Each client's websocket handshake goes to the router first, not straight to a specific backend."}, "router>server": {"d": "The router hashes the room id and always forwards to the same backend, so room state never needs a lookup or cross-server replication."}}, "walk": ["clients", "clients>router", "router", "router>server", "server"]},
  "sd:stateless-loop": {"nodes": {"w1": {"d": "The worker is disposable: it can be killed and replaced at any time without losing anything that matters, because it doesn't hold the state that matters."}, "env": {"d": "The environment holds the real state — files, running processes, an open sandbox — the thing that would actually be lost if it, rather than the worker, went away.", "links": [{"label": "Temporal: what durable execution is", "url": "https://docs.temporal.io/evaluate/understanding-temporal"}]}, "w2": {"d": "The new worker reattaches to the same environment the old one was using. Because the environment, not the worker, held the state, this is a clean handoff rather than a recovery process."}}, "edges": {"w1>env": {"d": "The worker's tools act on the environment, which is where the run's real state lives."}, "env>w2": {"d": "After the original worker crashes, a new worker reattaches to the same environment and picks up where it left off."}}, "walk": ["w1", "w1>env", "env", "env>w2", "w2"]},
  "sd:storage-events": {"nodes": {"storage": {"d": "Object storage is a bucket-style store that holds the uploaded bytes outside the application's own servers, addressed by key rather than a filesystem path.\n\nHere it is the origin of the whole flow: nothing downstream runs until an object actually lands here."}, "events": {"d": "Storage events are notifications the object store emits automatically when something happens to an object, here 'object created'. They decouple the upload from the processing: the uploader never has to call a webhook itself, the platform does it. Delivery is at-least-once, so a duplicate notification is possible."}, "proc": {"d": "Processor is the service that consumes an object-created event and does the real work on the file: a virus scan, a thumbnail, or extraction. It runs after the bytes are already durable in storage, so a slow scan never blocks the upload itself. Because events can arrive twice, this work needs to be safe to repeat."}, "meta": {"d": "Metadata row is the database record that tracks a file's lifecycle, moving from pending to ready once processing finishes. It is what the rest of the application actually queries; nothing queries the object store directly.", "links": [{"label": "Technique: metadata in the DB, bytes in object storage", "url": "SYSTEM%20DESIGN.html#/patterns/large-blobs/metadata-split"}]}}, "edges": {"storage>events": {"d": "The store fires this notification the instant an object finishes writing; it is asynchronous, so the uploader's request already returned before anything here runs."}, "events>proc": {"d": "The queue hands the event to a worker, which pulls the object by its key and runs scan or thumbnail logic on it."}, "proc>meta": {"d": "Once processing succeeds, the processor flips the row's status so the rest of the app knows the file is usable."}}, "walk": ["storage", "storage>events", "events", "events>proc", "proc", "proc>meta", "meta"]},
  "sd:streaming": {"nodes": {"model": {"d": "The model is generating a response one token at a time rather than all at once. Token generation is inherently sequential — each new token depends on the ones before it — so streaming exposes that sequence instead of buffering it until the end."}, "client": {"d": "The client is whatever renders the response as it arrives — a chat UI, a terminal, a voice pipeline. It shows tokens as they're generated, so the user sees the first words within a second or two instead of a blank screen for the full generation time.", "links": [{"label": "Technique: server-sent events", "url": "SYSTEM%20DESIGN.html#/patterns/real-time/sse"}]}, "verify": {"d": "Verify and persist is a second consumer of the same output — checking it against a schema, running a safety check, writing it to a database — that runs alongside the stream rather than blocking it.\n\nBecause it runs asynchronously, a slow verification step adds no latency to what the user sees; it can still reject or flag the answer after the fact."}}, "edges": {"model>client": {"d": "Tokens are pushed to the client the moment the model produces them, over a persistent connection such as server-sent events or a WebSocket."}, "model>verify": {"d": "The same token stream is also fed to a verification and persistence path running in parallel, off the user-facing critical path."}}, "walk": ["model", "model>client", "client", "model>verify", "verify"]},
  "sd:structured": {"nodes": {"gen": {"d": "Generate is instructed to produce output matching a fixed schema — specific fields, types, maybe character spans back into a source — rather than free-form prose.", "links": [{"label": "Lesson: structured outputs", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/11-llm-engineering/03-structured-outputs"}]}, "validate": {"d": "Schema validation checks the raw output actually parses against the schema: right fields, right types, spans that resolve to real text. A model can be told to follow a schema and still occasionally violate it; this is the check that catches that."}, "consumer": {"d": "Downstream is ordinary code that consumes the validated output directly; parsing a string isn't required because the shape is already guaranteed."}}, "edges": {"gen>validate": {"d": "The model's raw output, not yet trusted to match the schema, goes to validation first."}, "validate>consumer": {"d": "Only output that passes schema validation reaches the code that consumes it."}}, "walk": ["gen", "gen>validate", "validate", "validate>consumer", "consumer"]},
  "sd:ticketmaster:ticketmaster-high-level-design": {"nodes": {"client": {"d": "Whoever is browsing events or trying to buy tickets, on the web or a mobile app."}, "cdn": {"d": "Caches the pages for popular events at the edge, close to the client, so a viral on-sale doesn't send every page view straight to the origin.", "links": [{"label": "Pattern: CDN and edge caching", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-reads/cdn"}]}, "gw": {"d": "Routes every request to the right backend service and checks the caller is who they say they are."}, "queue": {"d": "A virtual queue that admits users into the booking flow at a controlled rate during a hot on-sale, instead of letting every request hit booking at once and collapse it.", "links": [{"label": "Pattern: load shedding and backpressure", "url": "SYSTEM%20DESIGN.html#/patterns/scaling-writes/load-shedding"}]}, "search": {"d": "Handles event search and browsing, backed by a dedicated search index rather than the transactional database, since search and booking have very different load shapes."}, "evt": {"d": "Serves an individual event's details, venue, times, seating chart, straight from the database."}, "book": {"d": "Owns the two-step purchase: put a temporary hold on a seat, then confirm it once payment succeeds. This is the one service in the diagram doing a real write under contention, many people trying to buy the same seat at once.", "links": [{"label": "Pattern: reservation (hold, then confirm)", "url": "SYSTEM%20DESIGN.html#/patterns/contention/reservation"}]}, "es": {"d": "A full-text index over event data, kept in sync with Postgres so search doesn't have to run against the transactional store.", "links": [{"label": "Pattern: inverted index (Elasticsearch)", "url": "SYSTEM%20DESIGN.html#/patterns/search/inverted"}]}, "db": {"d": "The source of truth for tickets and bookings: what actually got sold, to whom, confirmed inside a transaction."}, "redis": {"d": "Holds a seat reservation with a time-to-live: if the user doesn't complete payment before it expires, the seat is released automatically without anyone having to clean it up.", "links": [{"label": "Pattern: reservation (hold, then confirm)", "url": "SYSTEM%20DESIGN.html#/patterns/contention/reservation"}]}, "pay": {"d": "The external service that actually charges the card. Booking only confirms the seat in Postgres once this comes back successful."}}, "edges": {"client>cdn": {"d": "A page view for a popular event can be served straight from the CDN's cache."}, "client>gw": {"d": "Anything that isn't a cached page goes through the API gateway."}, "gw>search": {"d": "A search or browse request is routed to the search service."}, "gw>evt": {"d": "A request for one event's details is routed to the event service."}, "gw>queue": {"d": "During a popular on-sale, booking requests are routed through the waiting room first."}, "queue>book": {"d": "The waiting room admits a user into the booking service at a controlled rate."}, "search>es": {"d": "The search service queries Elasticsearch."}, "evt>db": {"d": "The event service reads event details from Postgres."}, "book>db": {"d": "Booking confirms a purchase in Postgres inside a transaction, once payment succeeds."}, "book>redis": {"d": "Booking places a time-limited seat hold in Redis before payment is attempted."}, "book>pay": {"d": "Booking charges the card through the payment provider."}, "db>es": {"d": "Changes in Postgres are streamed into Elasticsearch to keep search results current."}}, "walk": ["client", "client>cdn", "cdn", "client>gw", "gw", "gw>search", "search", "search>es", "es", "gw>evt", "evt", "evt>db", "db", "gw>queue", "queue", "queue>book", "book", "book>redis", "redis", "book>pay", "pay", "book>db", "db>es"]},
  "sd:timeouts-retries": {"nodes": {"client": {"d": "Client here is really the caller of a flaky dependency, not necessarily a browser — could be another service."}, "backoff": {"d": "Backoff+jitter is the retry policy: each retry waits longer than the last (1s, 2s, 4s) with randomness added, so many callers retrying the same failure don't all hit the dependency at once."}, "dep": {"d": "Dependency is the thing that timed out — the diagram assumes any remote call can be slow or fail, and builds the retry policy around that instead of trusting the call to succeed."}, "giveup": {"d": "Retry budget caps how many times a call is retried (here, 3) before giving up; without this cap a hung dependency could cause an unbounded pile-up of retries.", "links": [{"label": "Session: Things break at a hundred million", "url": "index.html#/s/4/1"}]}}, "edges": {"client>backoff": {"d": "A call to the dependency times out, and enters the backoff/retry logic instead of failing immediately."}, "backoff>dep": {"d": "The call is retried with a jittered delay so it doesn't collide with every other caller's retry; this happens asynchronously relative to the original request."}, "backoff>giveup": {"d": "Once the retry count exceeds the budget, backoff stops retrying and hands off to the give-up path."}, "giveup>client": {"d": "The caller gets a fast, explicit failure instead of hanging while retries keep failing."}}, "walk": ["client", "client>backoff", "backoff", "backoff>dep", "dep", "backoff>giveup", "giveup", "giveup>client"]},
  "sd:topk": {"nodes": {"stream": {"d": "An event stream is the raw sequence of things happening, in this diagram every occurrence of an item, arriving continuously and in no guaranteed order.\n\nIt is the input side: nothing here has been counted or ranked yet. A trending-topics feature might see tens of thousands of these events a second."}, "sketch": {"d": "A count-min sketch is a fixed-size array of counters that estimates how many times each item has appeared, without storing every item individually.\n\nEach event hashes into a few counter cells and increments them; reading an item's count takes the minimum across its cells, which caps how much unrelated items can inflate the estimate. It trades a small, one-sided overcount error for memory that does not grow with the number of distinct items, which matters when the stream carries millions of unique keys and a hash map per key is too much memory."}, "heap": {"d": "A top-K heap keeps the current best K items by approximate count, discarding everything outside the top K rather than keeping a full ranked list.\n\nIt reads estimates from the sketch and evicts its current lowest entry when a new item's estimate beats it. This is what makes 'top 10 trending now' cheap to serve: the answer is always a small heap, never a sort over the whole stream."}}, "edges": {"stream>sketch": {"d": "Every event increments its hashed counters in the sketch; this is the only write path, so the sketch's counts are always approximate, never exact."}, "sketch>heap": {"d": "The heap periodically reads an item's estimated count from the sketch and updates its ranking, evicting its current lowest-count member if a new item passes it."}}, "walk": ["stream", "stream>sketch", "sketch", "sketch>heap", "heap"]},
  "sd:transcript-checkpoint": {"nodes": {"worker": {"d": "The agent loop can crash mid-run — a process restart, an out-of-memory kill, a deploy — at any point, including mid-turn. The system has to assume this will happen, not treat it as exceptional."}, "transcript": {"d": "The transcript records every turn as it completes, durably, so a crash never loses more than the one turn in progress when it happened.", "links": [{"label": "Temporal: workflow execution, event history and replay", "url": "https://docs.temporal.io/workflow-execution"}, {"label": "Lesson: durable execution", "url": "https://github.com/rohitg00/ai-engineering-from-scratch/tree/main/phases/15-autonomous-systems/12-durable-execution"}]}, "w2": {"d": "The new worker doesn't need any special recovery logic beyond reading the transcript: it resumes at turn 37 because that's where the last checkpoint left off, and continues as if nothing happened."}}, "edges": {"worker>transcript": {"d": "Each completed turn is checkpointed to the transcript before the worker moves to the next one."}, "transcript>w2": {"d": "A new worker reads the transcript's last checkpoint, turn 37, and resumes exactly there."}}, "walk": ["worker", "worker>transcript", "transcript", "transcript>w2", "w2"]},
  "sd:unknown-results": {"nodes": {"worker": {"d": "The worker crashes while a tool call is in flight — not before it, not after it completes, but during it, which is the hard case: the call may have already taken effect on the far side."}, "call": {"d": "The tool call — pushing a commit, sending an email, charging a card — was in flight when the crash happened. Whether it completed on the remote system before the crash is genuinely unknown from the worker's side."}, "unknown": {"d": "An unknown result is explicitly not treated as a failure to be retried. Retrying blindly risks doing the action twice — sending the email again, charging the card again — which is often worse than the original crash."}, "check": {"d": "Reconcile looks up the actual remote state — did the commit land, did the email send — to find the truth, rather than guessing from the worker's own crash.", "links": [{"label": "Technique: idempotency", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/idempotency"}]}}, "edges": {"worker>call": {"d": "The worker crashes while this specific call is mid-flight, before it knows whether the call succeeded."}, "call>unknown": {"d": "Because the crash happened during the call, its outcome is genuinely unknown, not simply 'failed.'"}, "unknown>check": {"d": "Instead of retrying, the system looks up the remote system's actual state to find out what really happened."}}, "walk": ["worker", "worker>call", "call", "call>unknown", "unknown", "unknown>check", "check"]},
  "sd:vector": {"nodes": {"doc": {"d": "Passages are the raw text chunks being made searchable by meaning rather than by exact words."}, "embed": {"d": "Embed model turns text into a fixed-length vector such that semantically similar text produces nearby vectors; both documents and queries go through the same model.", "links": [{"label": "Session: Vectors and matrices", "url": "index.html#/s/3/2"}]}, "index": {"d": "Vector index (HNSW/IVF, ANN) stores those vectors and answers 'which stored vectors are closest to this one' approximately, trading a little accuracy for a lot of speed compared to checking every vector.", "links": [{"label": "Design: notebooklm uses pgvector at launch, a dedicated index only if partition counts or latency demand it", "url": "SYSTEM%20DESIGN.html#/designs/notebooklm/patterns"}]}, "query": {"d": "Query is the user's search text, which has to go through the same embedding model as the documents before it can be compared to them."}}, "edges": {"doc>embed": {"d": "Every passage is embedded once, ahead of any query, when the document is ingested."}, "embed>index": {"d": "The resulting vector is stored in the index alongside the passage it represents."}, "query>embed": {"d": "The query text is embedded through the same model used for documents; this consistency is what makes the comparison meaningful."}}, "walk": ["doc", "doc>embed", "embed", "embed>index", "index", "query", "query>embed"]},
  "sd:vertical-partitioning": {"nodes": {"writer": {"d": "Whoever is writing, to one of two very differently-shaped tables."}, "core": {"d": "Tables that need transactional guarantees and are read constantly: users, orders. Small in volume, high in importance per row."}, "events": {"d": "A separate store for high-volume data, like event logs, kept apart specifically so its sheer volume doesn't slow down queries against the core tables."}}, "edges": {"writer>core": {"d": "Transactional writes, users, orders, go to the core tables."}, "writer>events": {"d": "High-volume event writes go to a separate store entirely."}}, "walk": ["writer", "writer>core", "core", "writer>events", "events"]},
  "sd:websockets": {"nodes": {"client": {"d": "Can send a message to the server at any time, not just in reply to something the server sent."}, "server": {"d": "Can likewise send a message to the client at any time. Neither side has to wait for the other to speak first, the key difference from SSE's one-way stream."}}, "edges": {"client>server": {"d": "The client can send a message whenever it wants, not only as a request in reply to the server."}, "server>client": {"d": "The server can likewise push a message whenever it wants."}}, "walk": ["client", "client>server", "server", "server>client"]},
  "sd:worker-leases": {"nodes": {"w1": {"d": "Worker A holds a stale lease — it may still be running, unaware that its lease expired and was reassigned, perhaps after a long pause or a network partition that made it look dead when it wasn't."}, "w2": {"d": "Worker B holds the current lease, issued after the system decided worker A's lease had expired."}, "fence": {"d": "The fencing check compares the lease token attached to an incoming write against the current token on record. Only a write carrying the current token is accepted; a write from a worker holding an old token is rejected, even if that worker doesn't know yet that it's been superseded.", "links": [{"label": "Technique: distributed locking", "url": "SYSTEM%20DESIGN.html#/patterns/contention/distributed-lock"}]}, "store": {"d": "Task state is the shared state both workers might try to write to, the actual point of contention this whole mechanism protects."}}, "edges": {"w1>fence": {"d": "Worker A's write arrives carrying its old, expired lease token."}, "w2>fence": {"d": "Worker B's write arrives carrying the current lease token."}, "fence>store": {"d": "Only the write with the matching, current token is accepted into task state; the stale write is rejected regardless of arrival order."}}, "walk": ["w1", "w2", "w1>fence", "w2>fence", "fence", "fence>store", "store"]},
  "sd:worker-pool": {"nodes": {"api": {"d": "The tier that accepts requests and hands off actual work instead of doing it inline.\n\nIt scales independently of the workers — a burst of incoming requests doesn't require a burst of processing capacity at the same instant, because the queue absorbs the gap."}, "queue": {"d": "The buffer sitting between the fast API tier and the slower worker tier.\n\nIts depth is a direct signal of whether workers are keeping up — a permanently growing queue means the worker pool needs to scale up.", "links": [{"label": "How workers claim jobs without colliding: SKIP LOCKED", "url": "SYSTEM%20DESIGN.html#/patterns/contention/claim-skip-locked"}, {"label": "Session: throughput, latency, queues, backpressure", "url": "index.html#/s/1/1"}]}, "w1": {"d": "One worker in the pool, pulling jobs off the queue whenever it's free.\n\nWorkers are typically stateless and interchangeable — any of them can pick up any job."}, "w2": {"d": "A second worker, pulling independently and concurrently with the first.\n\nMore workers means more jobs processed per unit time, up to whatever the queue and downstream resources can sustain."}}, "edges": {"api>queue": {"d": "The API enqueues work instead of processing it inline, decoupling request handling from actual processing."}, "queue>w1": {"d": "Worker 1 pulls a job when it has capacity."}, "queue>w2": {"d": "Worker 2 pulls independently, in parallel with worker 1 — this is what lets throughput scale by adding more workers."}}, "walk": ["api", "api>queue", "queue", "queue>w1", "w1", "queue>w2", "w2"]},
  "sd:workflow-engine": {"nodes": {"engine": {"d": "The runtime (Temporal is the example given) that drives a workflow definition forward, one step at a time, and survives its own crashes.\n\nIt doesn't hold state in memory as the only copy — everything it needs to resume is written to history first.", "links": [{"label": "How valid transitions are enforced: explicit state machine", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/state-machine"}]}, "history": {"d": "An append-only, durable log of everything the workflow has done and every result it received.\n\nOn a crash, the engine doesn't restart the workflow from scratch — it replays history to reconstruct exactly where it left off, then continues."}, "activity": {"d": "A unit of work with a real side effect (an API call, a database write) that the engine runs and retries independently if it fails or the worker crashes mid-execution.\n\nActivities are where actual side effects happen; retrying one safely usually requires it to be idempotent.", "links": [{"label": "What makes a retried activity safe: idempotency keys", "url": "SYSTEM%20DESIGN.html#/patterns/multi-step/idempotency"}, {"label": "How failed attempts are retried: backoff and a DLQ", "url": "SYSTEM%20DESIGN.html#/patterns/long-running/retries-dlq"}]}, "timer": {"d": "A durable timer — for example, wait 72 hours — that survives process restarts, unlike a language-level sleep.\n\nBecause the wait is recorded in history rather than held in a process's memory, the engine can be redeployed or crash entirely during those 72 hours and still fire the timer on schedule."}}, "edges": {"engine>history": {"d": "The engine writes each step it takes to durable history before or as it executes, so nothing depends on process memory."}, "engine>activity": {"d": "The engine invokes an activity to perform an actual side effect."}, "activity>history": {"d": "The activity's result — success, failure, or output — is recorded to history so the engine, or its replacement after a crash, knows what happened."}, "engine>timer": {"d": "The engine can also just wait, durably, without holding a thread or process alive for the whole duration."}}, "walk": ["engine", "engine>history", "history", "engine>activity", "activity", "activity>history", "engine>timer", "timer"]},
  "sd:write-optimized": {"nodes": {"writer": {"d": "Appending a new write, the operation this storage engine is built to make cheap."}, "memtable": {"d": "An in-memory structure every write is appended to first, sequentially, which is why the write itself is fast: no random disk seek."}, "sstable": {"d": "An immutable, sorted file the memtable is flushed to once it's full, later merged with other SSTables by a background compaction process."}}, "edges": {"writer>memtable": {"d": "A write is appended to the in-memory memtable."}, "memtable>sstable": {"d": "Once full, the memtable is flushed to disk as an SSTable, and older SSTables are periodically compacted together."}}, "walk": ["writer", "writer>memtable", "memtable", "memtable>sstable", "sstable"]}
});
